  profilePixelLine(frame,x-w-2,y-h,x-w+1,y,1,255,255,255,150);
  profilePixelLine(frame,x+w+2,y-h,x+w-1,y,1,255,255,255,150);
  // glossy stripe
  if(alt) profileFill(frame,x-Math.max(1,Math.round(w*0.42)),y-h+1,2,h*2,255,255,255,185);
