async function useRaccoonSuit(env, interaction) {
  const user = getUserFromInteraction(interaction);
  if (!user) return;
  const player = await getPlayer(env, user.id);
  updatePlayerIdentity(player, interaction);

  if (raccoonMartCount(player, "raccoon_suit") < 1) {
    return sendText(env, interaction, "❌ You do not own a Raccoon Suit.");
  }

  if (Number(player.raccoonSuitStartedAt || 0) > 0) {
    const started = Number(player.raccoonSuitStartedAt || 0);
    const endsAt = started + 24 * 60 * 60 * 1000;
    if (Date.now() < endsAt) {
      const remainingHours = Math.max(1, Math.ceil((endsAt - Date.now()) / (60 * 60 * 1000)));
      return sendText(
        env,
        interaction,
        `🦝💼 **YOUR RACCOON SUIT IS ALREADY ACTIVE!**\n\n⏳ You have about **${remainingHours} hour${remainingHours === 1 ? "" : "s"}** left in your 24-hour payday event.\n💰 **${Number(player.raccoonSuitTotalEarned || 0).toLocaleString()} ✨** earned so far.`
      );
    }
    // A stale completed activation should never block a new suit.
    player.raccoonSuitStartedAt = 0;
    player.raccoonSuitNextPayoutAt = 0;
    player.raccoonSuitPayoutsMade = 0;
    player.raccoonSuitTotalEarned = 0;
  }

  consumeRaccoonMartItem(player, "raccoon_suit");
  const now = Date.now();
  player.raccoonSuitStartedAt = now;
  player.raccoonSuitNextPayoutAt = now + 60 * 60 * 1000;
  player.raccoonSuitPayoutsMade = 0;
  player.raccoonSuitTotalEarned = 0;
  await savePlayer(env, player, user.id);

  return sendText(
    env,
    interaction,
    `🦝💼 **RACCOON SUIT ACTIVATED!**\n\nThe raccoon corporation has hired you for the next **24 hours**. 😭\n\n⏰ **First payday:** 1 hour from now\n💰 **Hourly payout:** 15,000–300,000 ✨\n🎰 **24 random paydays**\n\nGood luck. The raccoon financial department is watching. 🦝💼`
  );
}

async function buyRaccoonMartItem(env, interaction, itemId) {
  const user = getUserFromInteraction(interaction);
  if (!user) return;
  const item = RACCOON_MART_ITEMS[itemId];
  if (!item) return sendText(env, interaction, "❌ That RaccoonMart item does not exist.");
  const player = await getPlayer(env, user.id);
  updatePlayerIdentity(player, interaction);

  if (itemId === "raccoon_empire" && raccoonMartCount(player, "raccoon_empire") > 0) {
    return sendText(
      env,
      interaction,
      "🏛️🦝 **You already own the Raccoon Empire License!**\n\nYour Empire is permanent, so you can only purchase one."
    );
  }

  if (Number(player.sparkles || 0) < item.price) {
    return sendText(env, interaction, `❌ You need **${item.price.toLocaleString()} sparkles**, but you only have **${Number(player.sparkles || 0).toLocaleString()}**.`);
  }
  player.sparkles -= item.price;
  setRaccoonMartCount(player, itemId, raccoonMartCount(player, itemId) + 1);

  if (itemId === "raccoon_empire") {
    // The purchase starts the 7-day clock. The first 20,000 ✨ dividend is
    // paid after a full 7 days, never immediately on purchase.
    player.raccoonEmpireLastDividendAt = Date.now();
  }

  player.shopPurchases = Number(player.shopPurchases || 0) + 1;
  player.badgeStats = player.badgeStats && typeof player.badgeStats === "object" ? player.badgeStats : {};
  player.badgeStats.sparklesSpent = Number(player.badgeStats.sparklesSpent || 0) + item.price;
  await savePlayer(env, player, user.id);
  await sendText(env, interaction,
    `🛒🦝 **PURCHASE COMPLETE!**\n\nYou bought **${item.name}** for **${item.price.toLocaleString()} ✨**.\n\n📦 You now own **${raccoonMartCount(player, itemId)}**.${itemId === "raccoon_empire" ? "\n\n🏛️ **YOUR EMPIRE IS NOW ACTIVE PERMANENTLY!**\n💰 **20,000 ✨ every 7 days**\n📈 **+20% on positive sparkle earnings**\n♾️ **Never expires.**" : itemId === "raccoon_suit" ? "\n\n🦝💼 **READY FOR ACTIVATION!**\n⏰ Activate it from **My RaccoonMart** to start your 24-hour payday event.\n💰 **24 random hourly payouts — 15,000 to 300,000 ✨ each.**" : ""}`,
    raccoonMartHomeRows(player)
  );
}

function hasActiveCourtSentence(player) {
  const fields = [
    "courtGameTimeoutUntil", "courtFortuneBanUntil", "courtRaccoonBanUntil",
    "courtRecycleBanUntil", "courtRiddleBanUntil", "courtUtilityLockUntil",
    "courtProbationUntil", "courtWatchUntil", "courtCriminalRecordUntil",
    "courtShameCornerUntil", "raccoonCourtTreeUntil", "raccoonCourtStinkEffectUntil",
    "courtRaccoonTitleUntil", "courtPublicShameUntil", "courtTrashReleaseUntil",
    "courtSpoonInvestigationUntil", "courtTreeConfiscationUntil"
  ];
  return fields.some(field => Number(player[field] || 0) > Date.now());
}

async function useJailFreeCard(env, interaction) {
  const user = getUserFromInteraction(interaction);
  if (!user) return;
  const player = await getPlayer(env, user.id);
  await refreshPunishmentState(env, player);
  if (!hasActiveCourtSentence(player)) {
    return sendText(env, interaction, "🎟️ The raccoons checked your record... you don't have an active Court sentence to escape from.");
  }
  if (!consumeRaccoonMartItem(player, "jail_free_card")) {
    return sendText(env, interaction, "❌ You don't have a Get Out of Jail Free Card.");
  }

  // Restore anything Court temporarily replaced, then clear Court timers.
  if (Number(player.raccoonCourtTreeUntil || 0) > 0) player.equipped.tree = player.raccoonCourtPreviousTree || "cherry";
  if (Number(player.raccoonCourtStinkEffectUntil || 0) > 0) player.equipped.effect = player.raccoonCourtPreviousEffect ?? null;
  if (Number(player.courtCriminalRecordUntil || 0) > 0 && player.courtPreviousTitle) player.equippedTitle = player.courtPreviousTitle;
  if (Number(player.courtRaccoonTitleUntil || 0) > 0 && player.courtRaccoonPreviousTitle && !player.courtPreviousTitle) player.equippedTitle = player.courtRaccoonPreviousTitle;

  const fields = [
    "courtGameTimeoutUntil", "courtFortuneBanUntil", "courtRaccoonBanUntil",
    "courtRecycleBanUntil", "courtRiddleBanUntil", "courtUtilityLockUntil",
    "courtProbationUntil", "courtWatchUntil", "courtCriminalRecordUntil",
    "courtShameCornerUntil", "raccoonCourtTreeUntil", "raccoonCourtStinkEffectUntil",
    "courtRaccoonTitleUntil", "courtPublicShameUntil", "courtTrashReleaseUntil",
    "courtSpoonInvestigationUntil", "courtTreeConfiscationUntil"
  ];
  for (const field of fields) player[field] = 0;
  player.courtTrashReleaseNextAt = 0;
  player.courtTrashReleaseChannelId = "";
  player.courtSpoonInvestigationLastAt = 0;
  player.courtPublicShameLastAt = 0;
  player.raccoonCourtPreviousTree = "";
  player.raccoonCourtPreviousEffect = null;
  player.courtPreviousTitle = "";
  player.courtRaccoonPreviousTitle = "";
  await savePlayer(env, player, user.id);
  await sendText(env, interaction,
    `🎟️🦝 **GET OUT OF JAIL FREE!**\n\nThe Court sentence has been cancelled. The raccoons are furious.\n\n📦 Cards remaining: **${raccoonMartCount(player, "jail_free_card")}**`,
    raccoonMartHomeRows(player)
  );
}

async function useCheeseProtection(env, interaction, itemId, durationMs = 0, uses = 0) {
  const user = getUserFromInteraction(interaction);
  if (!user) return;
  const player = await getPlayer(env, user.id);
  if (!consumeRaccoonMartItem(player, itemId)) return sendText(env, interaction, `❌ You don't have **${RACCOON_MART_ITEMS[itemId].name}**.`);
  const now = Date.now();
  if (uses) {
    player.raccoonShieldUses = Number(player.raccoonShieldUses || 0) + uses;
  } else {
    player.raccoonShieldUntil = Math.max(Number(player.raccoonShieldUntil || 0), now + durationMs);
  }
  await savePlayer(env, player, user.id);
  const detail = uses
    ? `🧀 One /raccoon attack will be blocked automatically.`
    : `🧀 /raccoon is blocked for **${durationMs >= 3 * 24 * 60 * 60 * 1000 ? "3 days" : "24 hours"}**.`;
  await sendText(env, interaction, `🧀🦝 **CHEESE PROTECTION ACTIVATED!**\n\n${detail}\n\n📦 Remaining: **${raccoonMartCount(player, itemId)}**`, raccoonMartHomeRows(player));
}

