async function getRaccoonMegaphoneJobs(env) {
  try {
    const raw = await env.TREE_DATA.get(RACCOON_MEGAPHONE_JOBS_KEY);
    const jobs = raw ? JSON.parse(raw) : [];
    return Array.isArray(jobs) ? jobs : [];
  } catch (error) {
    console.error("Failed to load Raccoon Megaphone jobs:", error);
    return [];
  }
}

async function saveRaccoonMegaphoneJobs(env, jobs) {
  await env.TREE_DATA.put(
    RACCOON_MEGAPHONE_JOBS_KEY,
    JSON.stringify(Array.isArray(jobs) ? jobs : [])
  );
}

async function processRaccoonMegaphoneJobs(env) {
  const now = Date.now();
  const jobs = await getRaccoonMegaphoneJobs(env);
  if (!jobs.length) return;

  const remaining = [];

  for (const job of jobs) {
    try {
      if (!job || !job.channelId || !job.targetId) continue;

      const sentCount = Number(job.sentCount || 0);
      const nextAt = Number(job.nextAt || 0);

      if (sentCount >= RACCOON_MEGAPHONE_TOTAL_MESSAGES) continue;

      if (now < nextAt) {
        remaining.push(job);
        continue;
      }

      const notices = Array.isArray(job.notices) && job.notices.length
        ? job.notices
        : raccoonMegaphoneNotices(job.targetId);

      const message = notices[randomInt(0, notices.length - 1)];
      await sendChannelMessage(env, job.channelId, message);

      const newSentCount = sentCount + 1;

      if (newSentCount < RACCOON_MEGAPHONE_TOTAL_MESSAGES) {
        remaining.push({
          ...job,
          sentCount: newSentCount,
          nextAt: nextAt + RACCOON_MEGAPHONE_INTERVAL
        });
      }
    } catch (error) {
      console.error("Raccoon Megaphone job failed:", error);
      // Keep failed jobs so a temporary Discord/Worker error does not erase them.
      remaining.push(job);
    }
  }

  await saveRaccoonMegaphoneJobs(env, remaining);
}

async function useMegaphone(env, interaction, targetId) {
  const user = getUserFromInteraction(interaction);
  if (!user || !targetId || targetId === user.id) return sendText(env, interaction, "📢 Choose another player for the Raccoon Megaphone.");
  const player = await getPlayer(env, user.id);
  if (!consumeRaccoonMartItem(player, "raccoon_megaphone")) return sendText(env, interaction, "❌ You don't have a Raccoon Megaphone.");

  const notices = raccoonMegaphoneNotices(targetId);
  const channelId = interaction.channel_id;
  const now = Date.now();

  // Fire the first announcement immediately. The remaining three are handled
  // by the Cloudflare scheduled worker at +15, +30, and +45 minutes.
  await sendChannelMessage(env, channelId, notices[randomInt(0, notices.length - 1)]);

  const jobs = await getRaccoonMegaphoneJobs(env);
  jobs.push({
    id: `megaphone_${user.id}_${targetId}_${now}_${randomInt(1000, 999999)}`,
    channelId: String(channelId),
    targetId: String(targetId),
    notices,
    sentCount: 1,
    nextAt: now + RACCOON_MEGAPHONE_INTERVAL,
    createdAt: now
  });
  await saveRaccoonMegaphoneJobs(env, jobs);

  await savePlayer(env, player, user.id);
  await sendText(env, interaction, `📢🦝 **MEGAPHONE FIRED!**\n\n<@${targetId}> is now getting the full Raccoon Megaphone treatment. 😭\n\n📣 Announcements: **4 total** — now, +15m, +30m, +45m.\n📦 Megaphones remaining: **${raccoonMartCount(player, "raccoon_megaphone")}**`, raccoonMartHomeRows(player));
}

async function useRaccoonBoomerang(env, interaction, targetId) {
  const user = getUserFromInteraction(interaction);
  if (!user || !targetId || targetId === user.id) {
    return sendText(env, interaction, "🦝🪃 Choose another player for the Raccoon Boomerang.");
  }

  const player = await getPlayer(env, user.id);
  const target = await getPlayer(env, targetId);
  const targetSparkles = Math.max(0, Number(target.sparkles || 0));

  if (targetSparkles < 2500) {
    return sendText(env, interaction, `❌ <@${targetId}> doesn't have enough sparkles for the Raccoon Boomerang. They need at least **2,500 ✨**.`);
  }
  if (!consumeRaccoonMartItem(player, "raccoon_boomerang")) {
    return sendText(env, interaction, "❌ You don't have a Raccoon Boomerang.");
  }

  const amount = randomInt(2500, 5000);

  if (rubberBandActive(target)) {
    const lost = Math.min(amount, Math.max(0, Number(player.sparkles || 0)));
    player.sparkles = Math.max(0, Number(player.sparkles || 0) - lost);
    target.sparkles = Number(target.sparkles || 0) + lost;
    await savePlayer(env, player, user.id);
    await savePlayer(env, target, targetId);
    return sendText(
      env,
      interaction,
      `🪢🪃💥 **RUBBER BAND!**\n\nThe Raccoon Boomerang bounced off <@${targetId}> and flew **RIGHT BACK** at <@${user.id}>! 😭\n\n💸 <@${user.id}> lost **${lost.toLocaleString()} ✨** and <@${targetId}> received them.`,
      raccoonMartHomeRows(player)
    );
  }

  const backfire = Math.random() < 0.20;

  if (backfire) {
    const lost = Math.min(amount, Math.max(0, Number(player.sparkles || 0)));
    player.sparkles = Math.max(0, Number(player.sparkles || 0) - lost);
    await savePlayer(env, player, user.id);
    return sendText(env, interaction,
      `🦝🪃💥 **THE RACCOON BOOMERANG BACKFIRED!**\n\nThe boomerang completely ignored <@${targetId}> and came flying straight back at you. 😭\n\n💸 **You lost ${lost.toLocaleString()} ✨.**\n\n📦 Boomerangs remaining: **${raccoonMartCount(player, "raccoon_boomerang")}**`,
      raccoonMartHomeRows(player)
    );
  }

  const stolen = Math.min(amount, targetSparkles);
  target.sparkles = Math.max(0, targetSparkles - stolen);
  player.sparkles = Number(player.sparkles || 0) + stolen;
  player.badgeStats = player.badgeStats && typeof player.badgeStats === "object" ? player.badgeStats : {};
  player.badgeStats.sparklesStolen = Number(player.badgeStats.sparklesStolen || 0) + stolen;

  await savePlayer(env, target, targetId);
  await savePlayer(env, player, user.id);
  return sendText(env, interaction,
    `🦝🪃 **RACCOON BOOMERANG!**\n\nYou launched a boomerang at <@${targetId}> and successfully stole **${stolen.toLocaleString()} ✨**! 😭\n\n💰 **Your haul:** +${stolen.toLocaleString()} ✨\n📦 Boomerangs remaining: **${raccoonMartCount(player, "raccoon_boomerang")}**`,
    raccoonMartHomeRows(player)
  );
}

