async function showLimitedSet(env, interaction, setId) {
  await deferInteraction(env, interaction, { update: true });
  const set = LIMITED_SHOP_SETS.find(x => x.id === setId);
  if (!set) {
    await sendText(env, interaction, "❌ That limited set doesn't exist.");
    return;
  }
  const user = getUserFromInteraction(interaction);
  const player = await getPlayer(env, user.id);
  const buttons = set.items.map(([itemId, label, buttonId]) => {
    const owned = player.inventory.includes(itemId);
    const price = SHOP_ITEMS[itemId].price;
    return button(
      owned ? `${label} Owned` : `${label} — ${price}`,
      buttonId,
      owned ? 2 : 1,
      owned
    );
  });
  const rows = [];
  for (let i = 0; i < buttons.length; i += 3) rows.push(row(...buttons.slice(i, i + 3)));
  rows.push(row(button("⬅️ Back to Limited Shop", "shop_limited", 2)));
  await sendText(
    env,
    interaction,
    `🎁 **${set.label}**\n\n${set.description}\n\nChoose an item to purchase. ✨`,
    rows
  );
}

/* =========================================================
   BUY ITEMS
========================================================= */

async function buyItem(
  env,
  interaction,
  itemId
) {
  /* Acknowledge immediately before KV/player work. */
  await deferInteraction(env, interaction, { update: true });
  const user =
    getUserFromInteraction(
      interaction
    );

  if (!user) return;

  const player =
    await getPlayer(
      env,
      user.id
    );

  updatePlayerIdentity(
    player,
    interaction
  );

  const item =
    SHOP_ITEMS[itemId];

  if (!item) {
    await sendText(
      env,
      interaction,
      "❌ That item doesn't exist."
    );

    return;
  }

  if (
    player.inventory.includes(
      itemId
    )
  ) {
    await sendText(
      env,
      interaction,
      `✅ You already own ${item.name}!`
    );

    return;
  }

  if (
    player.sparkles <
    item.price
  ) {
    await sendText(
      env,
      interaction,
      `❌ You need **${item.price} sparkles**, but you only have **${player.sparkles}**.`
    );

    return;
  }

  player.sparkles -=
    item.price;

  player.inventory.push(
    itemId
  );
  player.shopPurchases =
    Number(player.shopPurchases || 0) + 1;
  player.badgeStats = player.badgeStats && typeof player.badgeStats === "object" ? player.badgeStats : {};
  player.badgeStats.sparklesSpent = Number(player.badgeStats.sparklesSpent || 0) + Number(item.price || 0);

  // Unlock collector rewards immediately when this purchase completes a set.
  const hadFrostborn = Array.isArray(player.titles) && player.titles.includes("frostborn");
  const hadBlackIceEffect = Array.isArray(player.unlockedNameEffects) && player.unlockedNameEffects.includes("black_ice");
  unlockNameEffects(player);
  const unlockedBlackIceCollector = !hadFrostborn && player.titles.includes("frostborn") && !hadBlackIceEffect && player.unlockedNameEffects.includes("black_ice");

  if (
    itemId === "purr_princess_effect" ||
    itemId === "kitty_tree" ||
    itemId === "cozy_cat_background" ||
    itemId === "cat_decoration" ||
    itemId === "pumpkin_cat_decoration"
  ) {
    player.catItemBought = true;
  }

  await savePlayer(
    env,
    player
  );

  const collectorMessage = unlockedBlackIceCollector
    ? `\n\n🧊❄️ **BLACK ICE COMPLETE!** You collected the entire Black Ice Limited set!\n🏷️ **Title Unlocked:** Frostborn\n✨ **Name Effect Unlocked:** Black Ice`
    : "";

  await sendText(
    env,
    interaction,
    `🎉 You bought **${item.name}** for **${item.price} sparkles**!${collectorMessage}\n\nGo to **Customize** to equip it.`
  );
}

