async function equipTheme(
  env,
  interaction,
  theme
) {
  const u=getUserFromInteraction(interaction); if(u){const p=await getPlayer(env,u.id); await refreshPunishmentState(env,p); if(Number(p.raccoonCourtTreeUntil||0)>Date.now()) return sendText(env,interaction,`💩🌳 Your Stink Tree sentence is active for **${punishmentTimeText(p.raccoonCourtTreeUntil)}** more. Customization is locked.`); }
  await deferInteraction(env, interaction, { update: true });
  const user =
    getUserFromInteraction(
      interaction
    );

  const player =
    await getPlayer(
      env,
      user.id
    );

  const allowed = {
    cherry: true,

    halloween:
      player.inventory.includes(
        "halloween_background"
      ),

    candyland:
      player.inventory.includes(
        "candyland_background"
      ),

    magic_mushroom:
      player.inventory.includes(
        "magic_mushroom_background"
      ),

    field_day:
      player.inventory.includes(
        "field_day_background"
      ),

    red_forest:
      player.inventory.includes(
        "red_forest_background"
      ),

    stoned_birthday:
      player.inventory.includes(
        "stoned_birthday_background"
      ),

    birthday:
      player.inventory.includes(
        "birthday_background"
      ),

    cozy_cat:
      player.inventory.includes(
        "cozy_cat_background"
      ),

    green_glow:
      player.inventory.includes(
        "green_glow_background"
      ),

    prism_flutter:
      player.inventory.includes(
        "prism_flutter_background"
      ),

    lavender_twilight:
      player.inventory.includes(
        "lavender_twilight_background"
      ),

    world_of_flags:
      player.inventory.includes(
        "world_of_flags_background"
      ),

    ocean_opal:
      player.inventory.includes(
        "ocean_opal_background"
      ),

    fairy_hollow:
      player.inventory.includes("fairy_hollow_background"),

    glam:
      player.inventory.includes("glam_background"),

    black_cat_magic:
      player.inventory.includes("black_cat_magic_background"),

    dragon_realm:
      player.inventory.includes("dragon_realm_background"),

    inferno_king:
      player.inventory.includes("inferno_king_background"),

    thunder_god:
      player.inventory.includes("thunder_god_background"),

    black_ice:
      player.inventory.includes("black_ice_background"),

    werewives:
      player.inventory.includes(
        "werewives_background"
      ),

    golden_pickle:
      player.inventory.includes(
        "golden_pickle_background"
      ),

    midnight_rider:
      player.inventory.includes(
        "midnight_rider_background"
      )
  };

  if (!allowed[theme]) {
    await sendText(
      env,
      interaction,
      "❌ You don't own that background."
    );

    return;
  }

  player.equipped.theme =
    theme;

  await savePlayer(
    env,
    player
  );

  await sendText(
    env,
    interaction,
    "✨ Background equipped!"
  );
}

