/* =========================================================
   LEADERBOARD
========================================================= */

async function showLeaderboard(
  env,
  interaction
) {
  const keys =
    await listAllPlayerKeys(
      env
    );

  const players = [];

  for (const key of keys) {
    const player =
      await getPlayer(
        env,
        key
      );

    players.push(
      player
    );
  }

  players.sort(
    (a, b) => {
      const sparkleDifference =
        b.sparkles -
        a.sparkles;

      if (
        sparkleDifference !==
        0
      ) {
        return sparkleDifference;
      }

      const levelDifference =
        b.level -
        a.level;

      if (
        levelDifference !==
        0
      ) {
        return levelDifference;
      }

      return (
        getTreeHeight(b) -
        getTreeHeight(a)
      );
    }
  );

  const top =
    players.slice(0, 10);

  if (!top.length) {
    await sendText(
      env,
      interaction,
      "🏆 Nobody is on the leaderboard yet!"
    );

    return;
  }

  const lines =
    top.map(
      (player, index) =>
        `**${index + 1}.** ${getDisplayName(player)} — ⭐ ${player.sparkles} sparkles • Level ${player.level} • 🌳 ${getTreeHeight(player)} ft`
    );

  await sendText(
    env,
    interaction,
    `🏆 **Werewives Tree Leaderboard**\n\n${lines.join("\n")}`,
    [
      row(
        button(
          "🌳 Back to Tree",
          "back_tree",
          2
        )
      )
    ]
  );
}

