async function updateSoloLeaderboard(env, player, score) {
  const raw = await env.TREE_DATA.get("solo:leaderboard");
  let board = [];
  try { board = raw ? JSON.parse(raw) : []; } catch { board = []; }
  board = Array.isArray(board) ? board : [];
  const existing = board.find(x => x.userId === player.userId);
  if (existing) {
    if (score > Number(existing.score || 0)) {
      existing.score = score;
      existing.displayName = player.displayName || player.username || "Werewife";
      existing.title = player.equippedTitle || "";
    }
  } else {
    board.push({ userId: player.userId, displayName: player.displayName || player.username || "Werewife", score, title: player.equippedTitle || "" });
  }
  board.sort((a,b) => Number(b.score || 0) - Number(a.score || 0));
  board = board.slice(0, 10);
  await env.TREE_DATA.put("solo:leaderboard", JSON.stringify(board));
  return board;
}

async function getSoloLeaderboard(env) {
  const raw = await env.TREE_DATA.get("solo:leaderboard");
  try {
    const board = raw ? JSON.parse(raw) : [];
    return Array.isArray(board) ? board : [];
  } catch { return []; }
}

function unlockSoloTitles(player, mission) {
  if (!Array.isArray(player.titles)) player.titles = [];
  const newlyUnlocked = [];
  const unlock = id => {
    if (!player.titles.includes(id)) {
      player.titles.push(id);
      newlyUnlocked.push(id);
    }
  };
  unlock("survivor");
  if (mission.raccoonChoice) unlock("rabid_raccoon");
  if (mission.cash >= 3000) unlock("cheese_boss");
  if (mission.sparklesEarned >= 1000) unlock("sparkle_princess");
  if (mission.health === 1) unlock("lucky");
  if (mission.highestHeat >= 90) unlock("public_menace");
  if (mission.riskyChoices >= 5) unlock("bad_decision");
  if (mission.finalScore >= 5000) unlock("chaos_royalty");
  if (mission.heat <= 10) unlock("untouchable");
  if (mission.cash >= 2000) unlock("rich_goblin");
  if (mission.health === SOLO_START_HEALTH) unlock("iron_will");
  if (mission.buttonChoices >= 3) unlock("button_goblin");
  if (mission.round >= 10 && mission.finalScore >= 3500) unlock("ten_level_survivor");
  if (mission.finalScore >= 8000) unlock("story_master");
  return newlyUnlocked;
}

async function handleGamesMenu(env, interaction) {
  const user = getUserFromInteraction(interaction);
  if (!user) return;
  const player = await getPlayer(env, user.id);
  updatePlayerIdentity(player, interaction);
  await savePlayer(env, player);
  await sendText(env, interaction, `🎮 **WEREWIVES GAMES**\n\n👤 **${soloPlayerName(player)}**\n\n🕵️ **Solo Mission** — single-player strategic chaos\n🏝️ **Chaos Island** — multiplayer survival chaos\n💰 **Heist Game** — multiplayer social deduction\n🧪 **The Experiment** — secret clues + group decisions\n🦝💥 **Raccoon Rumble** — exactly 3 players, secret objectives + chaos\n🔎 **Who Stole the Sparkles?** — detective cases for 1+ players\n🌳⚔️ **Tree Battle** — battle another tree\n🌈 **Color Chaos** — pastel territory chaos\n\n🌳 The Tree is separate — use **/tree**.`, [
    row(button("🏝️ Chaos Island", "games:island", 1), button("💰 Heist Game", "games:heist", 2)),
    row(button("🧪 The Experiment", "games:experiment", 1), button("🕵️ Solo Mission", "games:solo", 3)),
    row(button("🌳⚔️ Tree Battle", "games:battle", 1), button("🌈 Color Chaos", "games:colorchaos", 3)),
    row(button("🦝💥 Raccoon Rumble", "games:rumble", 1), button("🔎 Sparkle Crime", "games:sparklecrime", 2)),
    row(button("🏆 Solo Leaderboard", "games:solo_leaderboard", 2), button("🏷️ Titles", "title:list", 3))
  ]);
}

async function handleSoloStart(env, interaction) {
  if (await checkGamePunishment(env, interaction)) return;

  const user = getUserFromInteraction(interaction);
  if (!user) return;
  const player = await getPlayer(env, user.id);
  updatePlayerIdentity(player, interaction);
  if (player.soloMission && player.soloMission.status === "playing") {
    await sendText(env, interaction, "❌ You already have a Solo Mission in progress. Finish it first!", soloMenuComponents());
    return;
  }
  const game = {
    id: `solo-${Date.now()}-${user.id}`,
    userId: user.id,
    playerName: soloPlayerName(player),
    status: "playing",
    round: 1,
    maxRounds: SOLO_MISSION_ROUNDS,
    health: SOLO_START_HEALTH,
    cash: SOLO_START_CASH,
    heat: SOLO_START_HEAT,
    score: 0,
    riskyChoices: 0,
    buttonChoices: 0,
    highestHeat: 0,
    sparklesEarned: 0,
    raccoonChoice: false,
    usedScenarioIds: [],
    currentScenario: null,
    currentChoice: null
  };
  soloPickScenario(game);
  player.soloMission = game;
  await savePlayer(env, player);
  await sendPublicText(env, interaction, soloGameText(game), soloChoiceRows(game));
}

async function finishSoloMission(env, interaction, player, game, aborted = false) {
  game.status = "ended";
  let finalScore = Math.max(0, Math.floor(Number(game.score || 0) + Number(game.cash || 0) * 2 + Number(game.health || 0) * 100 - Number(game.heat || 0) * 10));
  if (aborted) finalScore = Math.floor(finalScore * 0.25);
  game.finalScore = finalScore;
  player.soloRuns = Number(player.soloRuns || 0) + 1;
  if (!aborted) player.soloWins = Number(player.soloWins || 0) + 1;
  player.soloBestScore = Math.max(Number(player.soloBestScore || 0), finalScore);
  player.soloBestStash = Math.max(Number(player.soloBestStash || 0), Number(game.cash || 0));
  player.soloRiskyChoices = Math.max(Number(player.soloRiskyChoices || 0), Number(game.riskyChoices || 0));
  player.soloPerfectRuns = Number(player.soloPerfectRuns || 0) + (game.health === SOLO_START_HEALTH && !aborted ? 1 : 0);
  player.soloHighestHeat = Math.max(Number(player.soloHighestHeat || 0), Number(game.highestHeat || 0));
  const reward = aborted ? 0 : Math.min(1000, Math.max(50, Math.floor(finalScore / 20)));
  player.soloSparklesEarned = Number(player.soloSparklesEarned || 0) + reward;
  player.sparkles = Number(player.sparkles || 0) + reward;
  const newlyUnlockedTitles = unlockSoloTitles(player, { ...game, finalScore });
  player.soloMission = null;
  await savePlayer(env, player);
  if (!aborted) await updateSoloLeaderboard(env, player, finalScore);
  const titleText = newlyUnlockedTitles.length ? `\n🏷️ **NEW titles unlocked:** ${newlyUnlockedTitles.map(id => `**${SOLO_TITLES[id]?.name || id}**`).join(", ")}` : "";
  const content = aborted
    ? `🛑 **SOLO MISSION ABORTED**\n\nYour run score was **${finalScore}**. No sparkles awarded.\n\nYou can try again anytime. 🕵️`
    : `🏁 **SOLO MISSION COMPLETE!**\n\n${soloEnding(game)}\n\n👤 **${soloPlayerName(player)}**\n🏆 **Final Score:** ${finalScore}\n💰 **Final Stash:** ${game.cash}\n❤️ **Health:** ${game.health}/3\n🚨 **Highest Heat:** ${game.highestHeat}/100\n✨ **Sparkles Earned:** +${reward}${titleText}\n\n🏆 Check **/solo-leaderboard** to see where you rank!`;
  await editOriginalResponse(env, interaction, { content, components: [row(button("🕵️ Play Again", "solo:start", 1), button("🏆 Leaderboard", "games:solo_leaderboard", 2)), row(button("🏷️ Titles", "title:list", 3), button("🎮 Games", "games:menu", 2))] });
}

async function handleSoloChoice(env, interaction, choiceIndex) {
  const user = getUserFromInteraction(interaction);
  if (!user) return;
  const player = await getPlayer(env, user.id);
  updatePlayerIdentity(player, interaction);
  const game = player.soloMission;
  if (!game || game.status !== "playing") return sendText(env, interaction, "❌ You don't have an active Solo Mission. Use **/solo** to start one.");
  const index = Number(choiceIndex);
  const choice = game.currentScenario?.choices?.[index];
  if (!choice) return sendText(env, interaction, "❌ That Solo Mission choice is invalid.");
  game.currentChoice = index;
  if (choice.risky) game.riskyChoices = Number(game.riskyChoices || 0) + 1;
  if (String(choice.label).includes("raccoon") || String(choice.label).includes("Raccoon")) game.raccoonChoice = true;
  if (String(choice.label).includes("BUTTON") || String(choice.label).includes("button") || String(choice.label).includes("Press")) game.buttonChoices = Number(game.buttonChoices || 0) + 1;
  game.cash = Math.max(0, Number(game.cash || 0) + Number(choice.cash || 0));
  game.heat = Math.max(0, Math.min(SOLO_MAX_HEAT, Number(game.heat || 0) + Number(choice.heat || 0)));
  game.health = Math.max(0, Math.min(SOLO_START_HEALTH, Number(game.health || 0) + Number(choice.health || 0)));
  game.score += Number(choice.score || 0);
  game.highestHeat = Math.max(Number(game.highestHeat || 0), game.heat);
  game.sparklesEarned += Math.max(0, Math.floor(Number(choice.score || 0) / 4));
  const result = choice.message;
  if (game.health <= 0 || game.heat >= SOLO_MAX_HEAT || game.round >= game.maxRounds) {
    game.score += Math.max(0, game.health) * 100;
    await savePlayer(env, player);
    await acknowledge(env, interaction);
    await finishSoloMission(env, interaction, player, game, false);
    return;
  }
  game.round++;
  soloPickScenario(game);
  await savePlayer(env, player);
  await acknowledge(env, interaction);
  await editOriginalResponse(env, interaction, { content: `${result}\n\n${soloGameText(game)}`, components: soloChoiceRows(game) });
}

async function handleSoloAbort(env, interaction) {
  const user = getUserFromInteraction(interaction);
  if (!user) return;
  const player = await getPlayer(env, user.id);
  updatePlayerIdentity(player, interaction);
  const game = player.soloMission;
  if (!game || game.status !== "playing") return sendText(env, interaction, "❌ You don't have an active Solo Mission.");
  await acknowledge(env, interaction);
  await finishSoloMission(env, interaction, player, game, true);
}

async function handleSoloStatus(env, interaction) {
  const user = getUserFromInteraction(interaction);
  if (!user) return;
  const player = await getPlayer(env, user.id);
  updatePlayerIdentity(player, interaction);
  if (!player.soloMission || player.soloMission.status !== "playing") {
    await sendText(env, interaction, soloMissionMenuText(player), soloMenuComponents());
    return;
  }
  await sendText(env, interaction, soloGameText(player.soloMission), soloChoiceRows(player.soloMission));
}

async function handleSoloLeaderboard(env, interaction) {
  const board = await getSoloLeaderboard(env);
  if (!board.length) return sendText(env, interaction, "🏆 **SOLO MISSION LEADERBOARD**\n\nNo completed missions yet. Be the first! 🕵️");
  const lines = board.map((entry, i) => {
    const title = entry.title && SOLO_TITLES[entry.title]?.name ? ` ${SOLO_TITLES[entry.title].name}` : "";
    return `${i + 1}. **${entry.displayName}${title}** — **${entry.score} pts**`;
  });
  await sendText(env, interaction, `🏆 **SOLO MISSION LEADERBOARD**\n\n${lines.join("\n")}`);
}

function titleEditData(data){const {flags,...rest}=data||{};return rest;}
async function handleTitleList(env,interaction){ const data=await buildTitlesResponseData(env,interaction,"titles",0); return interaction.__deferred?editOriginalResponse(env,interaction,titleEditData(data)):sendText(env,interaction,"🏆 **MY TITLES**",data.components); }
async function handleNameEffectList(env,interaction){ const data=await buildTitlesResponseData(env,interaction,"effects",0); return interaction.__deferred?editOriginalResponse(env,interaction,titleEditData(data)):sendText(env,interaction,"✨ **NAME EFFECTS**",data.components); }
async function handleTitleEquip(env,interaction,titleId){
  const user=getUserFromInteraction(interaction); if(!user)return;
  const punishmentPlayer=await getPlayer(env,user.id); await refreshPunishmentState(env,punishmentPlayer);
  if(Number(punishmentPlayer.pickleJailUntil||0)>Date.now()) return sendText(env,interaction,"🥒 You are in Pickle Jail. Your **Criminal** title is not optional. 😭");
  if(Number(punishmentPlayer.courtCriminalRecordUntil||0)>Date.now()) return sendText(env,interaction,"⚖️ Your **Criminal Record** punishment has locked your title. 😭");
  if(Number(punishmentPlayer.courtRaccoonTitleUntil||0)>Date.now()) return sendText(env,interaction,"🦝 The court-appointed raccoon chose your title. You cannot change it yet. 😭");
  const player=punishmentPlayer; updatePlayerIdentity(player,interaction);
  if(!player.titles.includes(titleId)||!SOLO_TITLES[titleId])return sendText(env,interaction,"🔒 You haven't unlocked that title yet.");
  player.equippedTitle=titleId; await savePlayer(env,player);
  const response=await editOriginalResponse(env,interaction,titleEditData(await buildTitlesResponseData(env,interaction,"titles",0)));
  if(!response.ok) console.error("Title menu refresh failed:",response.status,await response.text());
}
async function handleTitleUnequip(env,interaction){
  const user=getUserFromInteraction(interaction); if(!user)return; const player=await getPlayer(env,user.id); await refreshPunishmentState(env,player);
  if(Number(player.pickleJailUntil||0)>Date.now()||Number(player.courtCriminalRecordUntil||0)>Date.now()||Number(player.courtRaccoonTitleUntil||0)>Date.now())return sendText(env,interaction,"⚖️ Your current court sentence does not allow you to change your title. 😭");
  player.equippedTitle=""; await savePlayer(env,player);
  const response=await editOriginalResponse(env,interaction,titleEditData(await buildTitlesResponseData(env,interaction,"titles",0)));
  if(!response.ok) console.error("Title unequip menu refresh failed:",response.status,await response.text());
}


/* =========================================================
   WHO STOLE THE SPARKLES?
   HUGE SOLO + MULTIPLAYER DETECTIVE GAME
========================================================= */
const CRIME_MAX_PLAYERS=8;
const CRIME_DIFFICULTIES={
  rookie:{suspects:5,evidence:8,reward:[250,900],name:"🟢 Rookie"},
  detective:{suspects:6,evidence:10,reward:[600,1800],name:"🔵 Detective"},
  investigator:{suspects:7,evidence:12,reward:[1200,3500],name:"🟣 Investigator"},
  master:{suspects:8,evidence:15,reward:[2500,7500],name:"🔴 Master Detective"},
  legendary:{suspects:8,evidence:18,reward:[5000,15000],name:"🖤 Legendary"}
};
const CRIME_SUSPECTS=[
  ["🦝","Raccoon","claims to run the treasury's night security"],
  ["🐸","Frank","claims to have been working at the bakery"],
  ["🐈","Cat","claims to have been shopping"],
  ["🐰","Bunny","claims to have been gardening"],
  ["🦊","Fox","claims to have been delivering packages"],
  ["🐻","Bear","claims to have been asleep"],
  ["🐧","Penguin","claims to have been counting inventory"],
  ["🦇","Batty","claims to have been fixing the lights"],
  ["🐿️","Squirrel","claims to have been collecting acorns"],
  ["🐹","Hammy","claims to have been hiding in the arcade"]
];
const CRIME_LOCATIONS=["🏦 Treasury","🍰 Bakery","🌳 Moon Garden","🛍️ Sparkle Shop","📦 Delivery Room","🎪 Raccoon Arcade","🔮 Crystal Room","🌙 Rooftop"];
const CRIME_METHODS=["a copied treasury key","a borrowed staff badge","a hidden maintenance tunnel","a forged inventory receipt","a delivery cart","a fake security inspection","a spare access code","a disguised courier box"];
const CRIME_MOTIVES=["wanted to pay an enormous debt","wanted to embarrass the treasury keeper","wanted to buy something ridiculously shiny","wanted revenge after a petty argument","thought the sparkles were being unfairly hoarded","wanted to fund a secret side business","mistook the treasury money for their own stash","wanted to impress the Raccoon Council"];
const CRIME_CASE_TYPES=[
  {id:"inside_job",name:"🏦 Inside Job",desc:"The thief needed access only an insider could obtain."},
  {id:"timeline",name:"⏰ Timeline Trap",desc:"The alibis look solid until the times are compared."},
  {id:"frame_job",name:"🎭 Frame Job",desc:"Someone planted evidence to make an innocent suspect look guilty."},
  {id:"double_cross",name:"🤝 Double Cross",desc:"A hidden accomplice may have helped the thief."},
  {id:"paper_trail",name:"🧾 Paper Trail",desc:"Receipts, logs, and transactions expose the theft."},
  {id:"witness",name:"👀 Witness Puzzle",desc:"Several witnesses saw different pieces of the crime."},
  {id:"locked_room",name:"🔐 Locked Treasury",desc:"The treasury looked impossible to enter."},
  {id:"chaos",name:"🎲 Chaos Case",desc:"More red herrings, stranger motives, and fewer obvious answers."}
];
const CRIME_TWISTS=[
  "The obvious suspect is innocent and has a perfectly legitimate reason for one suspicious clue.",
  "One witness is lying about something unrelated to the theft.",
  "The thief left a deliberate clue because they were overconfident.",
  "A piece of evidence was planted after the theft.",
  "The accomplice did not know the real plan until the final moment.",
  "The thief used a legitimate object in an illegitimate way.",
  "Two suspects are lying, but only one is lying about the crime."
];
function crimeShuffle(a){a=[...a];for(let i=a.length-1;i>0;i--){const j=randomInt(0,i);[a[i],a[j]]=[a[j],a[i]];}return a;}
function crimeDifficultyForPlayers(n){const r=Math.random();if(n<=1)return r<.55?"rookie":r<.85?"detective":r<.97?"investigator":"master";if(n<=3)return r<.15?"detective":r<.50?"investigator":r<.88?"master":"legendary";return r<.05?"investigator":r<.40?"master":"legendary";}
function crimeCaseName(){const a=["The Midnight","The Missing","The Glittering","The Great","The Suspicious","The Vanishing","The Ridiculous"],b=["Sparkle Job","Treasury Caper","Raccoon Heist","Midnight Theft","Golden Disaster","Treasury Mystery","Sparkle Scandal"];return `${a[randomInt(0,a.length-1)]} ${b[randomInt(0,b.length-1)]}`;}
function crimeCreateCase(playerCount=1,forcedDifficulty=null){
  const difficulty=forcedDifficulty||crimeDifficultyForPlayers(playerCount),cfg=CRIME_DIFFICULTIES[difficulty];
  const suspects=crimeShuffle(CRIME_SUSPECTS).slice(0,cfg.suspects).map((x,i)=>({id:`s${i}`,emoji:x[0],name:x[1],cover:x[2]}));
  const culprit=suspects[randomInt(0,suspects.length-1)];
  const canAccomplice=["investigator","master","legendary"].includes(difficulty);
  let accomplice=null;
  if(canAccomplice&&Math.random()<(difficulty==="legendary"?.48:.25))accomplice=crimeShuffle(suspects.filter(s=>s.id!==culprit.id))[0];
  const locations=crimeShuffle(CRIME_LOCATIONS).slice(0,Math.max(4,Math.ceil(cfg.suspects*.8)));
  const crimeLocation=locations[0],method=CRIME_METHODS[randomInt(0,CRIME_METHODS.length-1)],motive=CRIME_MOTIVES[randomInt(0,CRIME_MOTIVES.length-1)];
  const stolen=2500+randomInt(0,8)*1250+(difficulty==="legendary"?25000:0);
  const type=CRIME_CASE_TYPES[randomInt(0,CRIME_CASE_TYPES.length-1)],twist=CRIME_TWISTS[randomInt(0,CRIME_TWISTS.length-1)];
  const times=crimeShuffle(["10:05 PM","10:17 PM","10:29 PM","10:41 PM","10:53 PM","11:05 PM","11:17 PM","11:29 PM","11:41 PM"]);
  const culpritTime=times[randomInt(2,6)];
  const fakeTimes=crimeShuffle(times.filter(t=>t!==culpritTime));
  const alibis={};
  suspects.forEach((su,i)=>{
    const claimedLocation=locations[(i+1)%locations.length];
    const claimedTime=su.id===culprit.id?culpritTime:fakeTimes[i%fakeTimes.length];
    alibis[su.id]={location:claimedLocation,time:claimedTime};
  });

  // Build a solvable evidence chain. The evidence never names the thief directly;
  // instead it gives facts the players can cross-reference against the suspect dossiers.
  const evidence=[]; const add=(id,title,text,truth="neutral",importance=1)=>evidence.push({id,title,text,truth,importance});
  const accessPool=crimeShuffle(suspects.filter(s=>s.id!==culprit.id)).slice(0,Math.min(2,suspects.length-1));
  const accessEligible=crimeShuffle([culprit,...accessPool]);
  const accessNames=accessEligible.map(s=>`${s.emoji} ${s.name}`).join(", ");
  add("vaultlog","🏦 Treasury Log",`The treasury was opened at **${culpritTime}** using **${method}**. The log records the exact time, but not the thief.` ,"timeline",3);
  add("access","🔑 Access Register",`The ${method} was available to exactly **${accessEligible.length}** suspects: ${accessNames}. Anyone outside this group could not have used that method.` ,"access",4);
  add("camera","📸 Camera Fragment",`A blurry figure reached **${crimeLocation}** shortly before the theft. The figure's face is obscured; the camera timestamp matches the treasury log.` ,"timeline",3);
  add("route","👣 Escape Route",`The thief left **${crimeLocation}** toward **${locations[1]||locations[0]}**. Anyone claiming to be somewhere else at the theft time must explain how they could have reached the scene and returned.` ,"route",3);
  add("receipt","🧾 Time-Stamped Receipt",`A receipt at **${locations[1]||locations[0]}** is timestamped **${culpritTime}**. It proves that anyone claiming to be there at that exact time was not at the treasury.` ,"alibi",3);
  add("inventory","📦 Inventory Mismatch",`The item needed for **${method}** was signed out shortly before **${culpritTime}**. The record contains a partial signature matching the access register group, but not a full name.` ,"access",3);
  add("witness","👀 Witness Statement",`A witness saw the thief leave the treasury immediately after **${culpritTime}**. They could not identify a face, but they confirm the escape route.` ,"route",2);
  add("motive","💰 Motive File",`The thief had a plausible reason to want **${stolen.toLocaleString()} ✨**. Motive is supporting evidence only; it cannot establish guilt by itself.` ,"motive",1);
  const innocent=suspects.filter(s=>s.id!==culprit.id);
  if(innocent[0])add("planted","🎭 Planted Evidence",`${innocent[0].emoji} ${innocent[0].name}'s item was found near the treasury, but its timestamp proves it arrived **after** the theft.` ,"red",2);
  if(innocent[1])add("alibi","🕐 Alibi Receipt",`${innocent[1].emoji} ${innocent[1].name} has a receipt confirming part of their claimed whereabouts.` ,"red",1);
  if(innocent[2])add("witness2","🗣️ Confused Witness",`A witness initially points toward ${innocent[2].emoji} ${innocent[2].name}, then admits the viewing distance made the identification unreliable.` ,"red",1);
  if(accomplice)add("accomplice","🤝 Second Set of Footprints",`A second person helped cover the escape. The pattern proves an accomplice existed, but does not identify them.` ,"accomplice",3);
  else add("decoy","🧀 Extremely Suspicious Cheese","A half-eaten cheese wheel was found near the treasury. It is extremely suspicious. It is also completely unrelated.","decoy",0);

  const coreIds=["vaultlog","access","camera","receipt","route"];
  const coreEvidence=coreIds.map(id=>evidence.find(e=>e.id===id)).filter(Boolean);
  const optionalEvidence=crimeShuffle(evidence.filter(e=>!coreIds.includes(e.id)));
  const selected=[...coreEvidence,...optionalEvidence].slice(0,cfg.evidence);

  const suspectStatements={};
  suspects.forEach((su,i)=>{
    const isC=su.id===culprit.id,isA=accomplice?.id===su.id;
    const t=alibis[su.id].time,loc=alibis[su.id].location;
    const statements=[`I was at ${loc} around ${t}.`,`I had nothing to do with the treasury.`,`I don't remember seeing anyone suspicious.`,`I was busy with my own business that night.`];
    if(isC)statements[0]=`I was at ${loc} around ${t}. I wasn't anywhere near the treasury.`;
    if(isA)statements[2]=`I never helped anyone get into the treasury.`;
    suspectStatements[su.id]=statements;
  });

  return {id:`crime-${Date.now()}-${randomInt(1000,9999)}`,name:crimeCaseName(),difficulty,type:type.id,typeName:type.name,typeDescription:type.desc,twist,culpritId:culprit.id,accompliceId:accomplice?.id||"",suspects,locations,crimeLocation,method,motive,stolen,evidence:crimeShuffle(selected),suspectStatements,alibis,accessEligibleIds:accessEligible.map(s=>s.id),discovered:[],interrogated:[],contradictions:[],playerGuesses:{},playerIncorrectAccusations:{},accusation:null,accompliceGuess:"",accompliceGuesses:{},status:"playing",startedAt:Date.now(),incorrectAccusations:0,perfect:true};
}

function crimeCaseById(game,id){return (game.evidence||[]).find(e=>e.id===id);}
function crimeCaseText(game,privateMode=false,privateState=null){
  const state=privateState||null;
  const found=state?.discovered?.length ?? (game.discovered?.length||0),total=game.evidence?.length||0;
  const interrogationCount=state?.interrogated?.length ?? (game.interrogated?.length||0);
  const contradictionCount=state?.contradictions?.length ?? (game.contradictions?.length||0);
  const suspects=(game.suspects||[]).map(s=>{
    const a=game.alibis?.[s.id];
    return `${s.emoji} **${s.name}** — claims **${a?.location||"unknown"}** at **${a?.time||"unknown"}**`;
  }).join("\n");
  const playerCount=Object.keys(game.players||{}).length;
  const guessCount=Object.keys(game.playerGuesses||{}).length;
  return [`🔎 **WHO STOLE THE SPARKLES?**`,`📁 **${game.name}**`,`${game.typeName} • ${CRIME_DIFFICULTIES[game.difficulty]?.name||game.difficulty}`,"",`💰 **Stolen:** ${Number(game.stolen||0).toLocaleString()} ✨`,`🏦 **Scene:** ${game.crimeLocation}`,`🔎 **Evidence:** ${found}/${total}`,`💬 **Interrogations:** ${interrogationCount}`,`🚨 **Contradictions:** ${contradictionCount}`,game.mode==="multi"?`🗳️ **Guesses submitted:** ${guessCount}/${playerCount}`:"",`👤 **Suspect Dossiers**`,suspects,"",`_${game.typeDescription}_`,...(privateMode?["","🔐 **PRIVATE INVESTIGATION PANEL**","Use the evidence and suspect alibis together. Interrogations can confirm a contradiction, but they are not the only way to solve the case."]: ["","🕵️ Use **Investigate** to open your private detective panel."])].filter(Boolean).join("\n");
}

function crimePublicRows(game){
  if(game.status==="lobby")return [row(button("➕ Join Case",`crime:join:${game.id}`,1),button("🚨 Start Case",`crime:start:${game.id}`,3)),row(button("🛑 Leave Case",`crime:leave:${game.id}`,4))];
  if(game.status==="playing")return [row(button("🔎 Investigate",`crime:investigate:${game.id}`,1),button("📊 Case Status",`crime:status:${game.id}`,2)),row(button("🗳️ Make Accusation",`crime:accuse:${game.id}`,4)),row(button("🛑 End Case",`crime:end:${game.id}`,4))];
  return [row(button("🔎 New Solo Case","crime:solo:new",1),button("🔎 New Multiplayer Case","crime:create",2))];
}
function crimePrivateState(game,userId){
  if(!game.privateInvestigations||typeof game.privateInvestigations!=="object")game.privateInvestigations={};
  if(!game.privateInvestigations[userId])game.privateInvestigations[userId]={discovered:[],interrogated:[],contradictions:[]};
  const state=game.privateInvestigations[userId];
  if(!Array.isArray(state.discovered))state.discovered=[];
  if(!Array.isArray(state.interrogated))state.interrogated=[];
  if(!Array.isArray(state.contradictions))state.contradictions=[];
  return state;
}
function crimePrivateRows(game,privateState=null){
  const state=privateState||{discovered:game.discovered||[],interrogated:game.interrogated||[],contradictions:game.contradictions||[]};
  // Each multiplayer detective gets their own investigation notebook.
  // Evidence/interrogation buttons are therefore independent per player.
  const rows=[];const ev=(game.evidence||[]).slice(0,20);
  for(let i=0;i<ev.length;i+=5){
    const buttons=[];
    for(let j=i;j<Math.min(i+5,ev.length);j++){
      const e=ev[j];
      buttons.push(button(`🔎 ${j+1}. ${e.title.slice(0,20)}`,`crime:evidence:${game.id}:${e.id}`,2,state.discovered.includes(e.id)));
    }
    rows.push(row(...buttons));
  }
  const controls=[
    button("💬 Interrogate",`crime:interrogate:${game.id}`,1),
    button("🧩 My Theory",`crime:theory:${game.id}`,2),
    button("🗳️ Accuse Thief",`crime:accuse:${game.id}`,4),
    button("⬅️ Case Board",`crime:board:${game.id}`,2)
  ];
  if(game.accompliceId)controls.push(button("🤝 Accomplice",`crime:accomplice:${game.id}`,2));
  rows.push(row(...controls));
  return rows;
}
function crimeAccusationRows(game){const rows=[];for(let i=0;i<game.suspects.length;i+=3)rows.push(row(...game.suspects.slice(i,i+3).map(s=>button(`${s.emoji} ${s.name}`,`crime:pickaccuse:${game.id}:${s.id}`,2))));return rows;}
function crimeAccompliceRows(game){const rows=[];for(let i=0;i<game.suspects.length;i+=3)rows.push(row(...game.suspects.slice(i,i+3).map(s=>button(`${s.emoji} ${s.name}`,`crime:pickaccomplice:${game.id}:${s.id}`,2))));return rows;}
function crimeInterrogateRows(game,privateState=null){
  const state=privateState||{interrogated:game.interrogated||[]};
  const avail=game.suspects.filter(s=>!state.interrogated.includes(s.id));
  const rows=[];for(let i=0;i<avail.length;i+=2)rows.push(row(...avail.slice(i,i+2).map(s=>button(`${s.emoji} ${s.name}`,`crime:question:${game.id}:${s.id}`,2))));
  rows.push(row(button("⬅️ Back",`crime:investigate:${game.id}`,2)));return rows;
}
function crimeUnlockTitles(player,stats){
  if(!Array.isArray(player.titles))player.titles=[];const out=[];const unlock=id=>{if(!player.titles.includes(id)){player.titles.push(id);out.push(id);}};
  if(stats.solved>=1)unlock("case_cracker");if(stats.evidence>=25)unlock("evidence_goblin");if(stats.contradictions>=10)unlock("lie_detector");if(stats.solved>=10)unlock("red_string_menace");if(stats.masterPerfect)unlock("master_detective");if(stats.solved>=25)unlock("raccoon_sherlock");if(stats.cleanCases>=5)unlock("clean_record");if(stats.interrogations>=25)unlock("interrogator");if(stats.reward>=10000)unlock("cold_case_crusher");if(stats.allEvidence)unlock("crime_scene_diva");if(stats.accomplice)unlock("accomplice_hunter");return out;
}
async function crimeSavePlayerResult(env,player,game,mode,allEvidence=false,correctGuess=true,privateState=null){
  const evidenceCount=privateState?.discovered?.length ?? (game.discovered?.length||0);
  const contradictionCount=privateState?.contradictions?.length ?? (game.contradictions?.length||0);
  const interrogationCount=privateState?.interrogated?.length ?? (game.interrogated?.length||0);
  const reward=Math.max(CRIME_DIFFICULTIES[game.difficulty]?.reward?.[0]||250,Math.min(CRIME_DIFFICULTIES[game.difficulty]?.reward?.[1]||15000,Math.floor(Number(game.stolen||0)*.12+evidenceCount*100+contradictionCount*175)));
  const solved=game.status==="solved";
  const playerSolved=mode==="multi" ? (solved&&correctGuess) : solved;
  player.crimeCases=Number(player.crimeCases||0)+1;
  if(playerSolved){player.crimeSolved=Number(player.crimeSolved||0)+1;player.crimeBestCase=Math.max(Number(player.crimeBestCase||0),Number(game.stolen||0));if(mode==="solo")player.crimeSoloWins=Number(player.crimeSoloWins||0)+1;else player.crimeMultiplayerWins=Number(player.crimeMultiplayerWins||0)+1;if(Number(game.playerIncorrectAccusations?.[player.userId]||0)===0)player.crimePerfectCases=Number(player.crimePerfectCases||0)+1;player.crimeEvidenceFound=Number(player.crimeEvidenceFound||0)+evidenceCount;player.crimeContradictions=Number(player.crimeContradictions||0)+contradictionCount;player.crimeInterrogations=Number(player.crimeInterrogations||0)+interrogationCount;player.crimeAccusations=Number(player.crimeAccusations||0)+1;player.crimeCorrectAccusations=Number(player.crimeCorrectAccusations||0)+1;player.crimeBestReward=Math.max(Number(player.crimeBestReward||0),reward);player.crimeDailyCases=Number(player.crimeDailyCases||0)+1;player.sparkles=Number(player.sparkles||0)+reward;}
  const stats={solved:Number(player.crimeSolved||0),evidence:Number(player.crimeEvidenceFound||0),contradictions:Number(player.crimeContradictions||0),interrogations:Number(player.crimeInterrogations||0),cleanCases:Number(player.crimePerfectCases||0),reward:Number(player.crimeBestReward||0),allEvidence,masterPerfect:playerSolved&&game.difficulty==="master"&&Number(game.playerIncorrectAccusations?.[player.userId]||0)===0&&allEvidence,accomplice:playerSolved&&game.accompliceGuesses?.[player.userId]===game.accompliceId};
  const titles=crimeUnlockTitles(player,stats);await savePlayer(env,player);
  if(playerSolved&&reward>0){let raw=await env.TREE_DATA.get("sparklecrime:leaderboard"),board=[];try{board=raw?JSON.parse(raw):[]}catch{}if(!Array.isArray(board))board=[];board.push({userId:player.userId,name:player.displayName||player.username||"Werewife",reward,caseName:game.name});board.sort((a,b)=>Number(b.reward)-Number(a.reward));await env.TREE_DATA.put("sparklecrime:leaderboard",JSON.stringify(board.slice(0,25)));}
  return {reward,titles};
}
async function getCrimeGame(env,guildId){return (await getGuildState(env,guildId)).sparkleCrime||null;}
async function saveCrimeGame(env,guildId,game){const state=await getGuildState(env,guildId);state.sparkleCrime=game;await saveGuildState(env,guildId,state);}
async function getCrimePrivateGame(env,interaction,gameId){
  const u=getUserFromInteraction(interaction);if(!u)return null;
  const multi=await getCrimeGame(env,interaction.guild_id);
  if(multi?.id===gameId&&multi.status==="playing")return {game:multi,mode:"multi",player:null,userId:u.id,privateState:crimePrivateState(multi,u.id)};
  const p=await getPlayer(env,u.id);
  if(p.sparkleCrimeSolo?.id===gameId&&p.sparkleCrimeSolo.status==="playing")return {game:p.sparkleCrimeSolo,mode:"solo",player:p,userId:u.id,privateState:{discovered:p.sparkleCrimeSolo.discovered||[],interrogated:p.sparkleCrimeSolo.interrogated||[],contradictions:p.sparkleCrimeSolo.contradictions||[]}};
  return null;
}
async function crimeInterrogateOne(env,interaction,ctx,suspectId){
  const game=ctx.game,suspect=game.suspects.find(s=>s.id===suspectId),state=ctx.privateState||crimePrivateState(game,ctx.userId);if(!suspect)return sendText(env,interaction,"❌ That suspect is unavailable.");
  if(!state.interrogated.includes(suspectId))state.interrogated.push(suspectId);
  const statements=game.suspectStatements[suspectId]||[],line=statements[randomInt(0,statements.length-1)];
  const alibi=game.alibis?.[suspectId];
  const vault=game.evidence?.find(e=>e.id==="vaultlog");
  const crimeTime=vault?.text?.match(/\*\*(.*?)\*\*/)?.[1]||"";
  const hasTimelineConflict=Boolean(alibi?.time===crimeTime&&alibi?.location!==game.crimeLocation);
  const hasAccessConflict=Array.isArray(game.accessEligibleIds)&&!game.accessEligibleIds.includes(suspectId);
  // Interrogation is no longer a built-in lie detector. A contradiction only
  // appears when the player's gathered facts expose a real conflict.
  const contradiction=hasTimelineConflict&&!hasAccessConflict;
  let extra="";
  if(contradiction&&!state.contradictions.includes(suspectId)){state.contradictions.push(suspectId);extra="\n\n🚨 **TIMELINE CONFLICT.** Their statement does not fit the documented time and access records. You must decide what that means.";}
  if(ctx.mode==="multi"){
    if(!game.interrogated.includes(suspectId))game.interrogated.push(suspectId);
    if(contradiction&&!game.contradictions.includes(suspectId))game.contradictions.push(suspectId);
    await saveCrimeGame(env,interaction.guild_id,game);
  }else{game.interrogated=state.interrogated;game.contradictions=state.contradictions;ctx.player.crimeInterrogations=Number(ctx.player.crimeInterrogations||0)+1;await savePlayer(env,ctx.player);}
  await sendText(env,interaction,`💬 **${suspect.emoji} ${suspect.name}**\n\n> ${line}\n\n_${suspect.cover}._${extra}\n\n🧠 **Don't treat an interrogation as proof. Compare it against the evidence.**`,crimePrivateRows(game,state));
}
async function handleCrimeSoloStart(env,interaction){if(await checkGamePunishment(env,interaction))return;const u=getUserFromInteraction(interaction);if(!u)return;const p=await getPlayer(env,u.id);updatePlayerIdentity(p,interaction);if(p.sparkleCrimeSolo?.status==="playing")return sendText(env,interaction,"❌ You already have a detective case open. Finish it first.");const game=crimeCreateCase(1);game.ownerId=u.id;game.mode="solo";p.sparkleCrimeSolo=game;await savePlayer(env,p);await sendText(env,interaction,crimeCaseText(game,true),crimePrivateRows(game));}
async function handleCrimeSoloAccuse(env,interaction,suspectId){
  const u=getUserFromInteraction(interaction);if(!u)return;const p=await getPlayer(env,u.id),g=p.sparkleCrimeSolo;if(!g||g.status!=="playing")return sendText(env,interaction,"❌ No active detective case.");
  if(suspectId!==g.culpritId){g.incorrectAccusations++;g.perfect=false;await savePlayer(env,p);return sendText(env,interaction,"❌ **WRONG ACCUSATION.** The case remains open, but your perfect record is gone.",crimePrivateRows(g,ctx.privateState));}
  g.status="solved";const all=g.discovered.length>=g.evidence.length;const r=await crimeSavePlayerResult(env,p,g,"solo",all);p.sparkleCrimeSolo=null;await savePlayer(env,p);
  const culprit=g.suspects.find(s=>s.id===g.culpritId),acc=g.accompliceId?g.suspects.find(s=>s.id===g.accompliceId):null;
  const titleText=r.titles.length?`\n🏷️ **NEW TITLES:** ${r.titles.map(t=>SOLO_TITLES[t].name).join(", ")}`:"";
  await sendText(env,interaction,[`🧑‍⚖️ **CASE CLOSED — ${g.name}**`,"",`🚨 **THIEF:** ${culprit.emoji} **${culprit.name}**`,g.accompliceId?`🤝 **ACCOMPLICE:** ${acc?.emoji} **${acc?.name}**`:"🤝 **ACCOMPLICE:** None",`🔐 **METHOD:** ${g.method}`,`🎭 **MOTIVE:** They ${g.motive}.`,`🧩 **CASE TYPE:** ${g.typeName}`,`🧠 **THE TWIST:** ${g.twist}`,"",`🔎 Evidence: **${g.discovered.length}/${g.evidence.length}**`,`🚨 Contradictions: **${g.contradictions.length}**`,`✨ **REWARD: +${r.reward.toLocaleString()} ✨**`,titleText].join("\n"),[row(button("🔎 New Case","crime:solo:new",1),button("🎮 Games","games:menu",2))]);}
async function handleCrimeCreate(env,interaction){const u=getUserFromInteraction(interaction);if(!u)return;const st=await getGuildState(env,interaction.guild_id);if(st.sparkleCrime&&["lobby","playing"].includes(st.sparkleCrime.status))return sendText(env,interaction,"❌ There is already an active Sparkle Crime case.");const g=crimeCreateCase(2);g.status="lobby";g.ownerId=u.id;g.players={[u.id]:{id:u.id}};await saveCrimeGame(env,interaction.guild_id,g);await sendPublicText(env,interaction,`🔎 **WHO STOLE THE SPARKLES? — CASE LOBBY**\n\n📁 **${g.name}**\n${g.typeName}\n\n👥 Players: **1/${CRIME_MAX_PLAYERS}**\n\nThe host can start when ready.`,crimePublicRows(g));}
async function handleCrimeJoin(env,interaction){const u=getUserFromInteraction(interaction);if(!u)return;const g=await getCrimeGame(env,interaction.guild_id);if(!g||g.status!=="lobby")return sendText(env,interaction,"❌ No open Sparkle Crime lobby.");if(g.players[u.id])return sendText(env,interaction,"❌ You are already in this case.");if(Object.keys(g.players).length>=CRIME_MAX_PLAYERS)return sendText(env,interaction,"❌ This case is full.");g.players[u.id]={id:u.id};await saveCrimeGame(env,interaction.guild_id,g);await editOriginalResponse(env,interaction,{content:`🔎 **WHO STOLE THE SPARKLES? — CASE LOBBY**\n\n📁 **${g.name}**\n${g.typeName}\n\n👥 Players: **${Object.keys(g.players).length}/${CRIME_MAX_PLAYERS}**\n\n${Object.keys(g.players).map(id=>`• <@${id}>`).join("\n")}\n\nThe host can start when ready.`,components:crimePublicRows(g)});}
async function handleCrimeLeave(env,interaction){const u=getUserFromInteraction(interaction);if(!u)return;const g=await getCrimeGame(env,interaction.guild_id);if(!g||g.status!=="lobby")return sendText(env,interaction,"❌ No open lobby.");delete g.players[u.id];if(!Object.keys(g.players).length){const st=await getGuildState(env,interaction.guild_id);st.sparkleCrime=null;await saveGuildState(env,interaction.guild_id,st);return sendText(env,interaction,"🗑️ Sparkle Crime lobby closed.");}if(g.ownerId===u.id)g.ownerId=Object.keys(g.players)[0];await saveCrimeGame(env,interaction.guild_id,g);await editOriginalResponse(env,interaction,{content:`🔎 **WHO STOLE THE SPARKLES? — CASE LOBBY**\n\n📁 **${g.name}**\n\n👥 Players: **${Object.keys(g.players).length}/${CRIME_MAX_PLAYERS}**\n\n${Object.keys(g.players).map(id=>`• <@${id}>`).join("\n")}`,components:crimePublicRows(g)});}
async function handleCrimeStart(env,interaction){const u=getUserFromInteraction(interaction);if(!u)return;const g=await getCrimeGame(env,interaction.guild_id);if(!g||g.status!=="lobby")return sendText(env,interaction,"❌ No Sparkle Crime lobby.");if(g.ownerId!==u.id)return sendText(env,interaction,"❌ Only the host can start the case.");if(Object.keys(g.players).length<2)return sendText(env,interaction,"❌ Multiplayer cases need at least **2 players**.");const fresh=crimeCreateCase(Object.keys(g.players).length);fresh.id=g.id;fresh.ownerId=g.ownerId;fresh.players=g.players;fresh.mode="multi";fresh.privateInvestigations={};for(const uid of Object.keys(fresh.players||{}))fresh.privateInvestigations[uid]={discovered:[],interrogated:[],contradictions:[]};await saveCrimeGame(env,interaction.guild_id,fresh);await editOriginalResponse(env,interaction,{content:crimeCaseText(fresh,false),components:crimePublicRows(fresh)});}
async function handleCrimeInvestigate(env,interaction){const g=await getCrimeGame(env,interaction.guild_id),u=getUserFromInteraction(interaction);if(!g||g.status!=="playing")return sendText(env,interaction,"❌ The case is not active.");if(!u||!g.players?.[u.id])return sendText(env,interaction,"❌ You are not part of this case.");const state=crimePrivateState(g,u.id);await saveCrimeGame(env,interaction.guild_id,g);await sendText(env,interaction,crimeCaseText(g,true,state),crimePrivateRows(g,state));}
async function handleCrimeEvidence(env,interaction,gameId,evidenceId){const ctx=await getCrimePrivateGame(env,interaction,gameId);if(!ctx)return sendText(env,interaction,"❌ That detective case is no longer active.");const ev=crimeCaseById(ctx.game,evidenceId);if(!ev)return sendText(env,interaction,"❌ That evidence no longer exists.");const state=ctx.privateState;if(!state.discovered.includes(evidenceId))state.discovered.push(evidenceId);if(ctx.mode==="multi"){if(!ctx.game.discovered.includes(evidenceId))ctx.game.discovered.push(evidenceId);await saveCrimeGame(env,interaction.guild_id,ctx.game);}else{ctx.game.discovered=state.discovered;await savePlayer(env,ctx.player);}await sendText(env,interaction,`🔎 **${ev.title}**\n\n${ev.text}`,crimePrivateRows(ctx.game,state));}
async function handleCrimeInterrogateMenu(env,interaction,gameId){const ctx=await getCrimePrivateGame(env,interaction,gameId);if(!ctx)return sendText(env,interaction,"❌ No active detective case.");await sendText(env,interaction,"💬 **WHO DO YOU WANT TO INTERROGATE?**\n\nChoose anyone you have not personally questioned yet. Other detectives can question the same suspects independently.",crimeInterrogateRows(ctx.game,ctx.privateState));}
async function handleCrimeTheory(env,interaction,gameId){const ctx=await getCrimePrivateGame(env,interaction,gameId);if(!ctx)return sendText(env,interaction,"❌ No active case.");const s=ctx.privateState;await sendText(env,interaction,`🧠 **YOUR CASE THEORY**\n\nEvidence YOU found: **${s.discovered.length}/${ctx.game.evidence.length}**\nPeople YOU questioned: **${s.interrogated.length}**\nConflicts YOU found: **${s.contradictions.length}**\n\nNo automatic lie detector. No clue names the thief for you. Cross-reference times, locations, access, routes, and statements. 😈`,crimePrivateRows(ctx.game,s));}
async function handleCrimeAccuseMenu(env,interaction,gameId){
  const ctx=await getCrimePrivateGame(env,interaction,gameId);if(!ctx)return sendText(env,interaction,"❌ No active case.");
  if(ctx.mode==="multi"){
    const uid=getUserFromInteraction(interaction)?.id;
    if(uid&&ctx.game.playerGuesses?.[uid])return sendText(env,interaction,`🗳️ **YOUR GUESS IS LOCKED IN.**\n\nYou guessed **${ctx.game.suspects.find(s=>s.id===ctx.game.playerGuesses[uid])?.name||"Unknown"}**.\n\nWait for the other detectives to submit their guesses.`,crimePrivateRows(ctx.game,ctx.privateState));
  }
  await sendText(env,interaction,"🗳️ **WHO DO YOU ACCUSE?**\n\nYour accusation is **your own private guess**. In multiplayer, every detective gets one independent guess. The case closes after everyone has submitted.",crimeAccusationRows(ctx.game));
}
async function handleCrimeAccusePick(env,interaction,gameId,suspectId){
  const ctx=await getCrimePrivateGame(env,interaction,gameId);if(!ctx)return sendText(env,interaction,"❌ No active case.");
  const g=ctx.game,u=getUserFromInteraction(interaction);if(!u)return;
  if(ctx.mode!=="multi")return handleCrimeSoloAccuse(env,interaction,suspectId);
  if(g.playerGuesses?.[u.id])return sendText(env,interaction,"🗳️ **YOU ALREADY SUBMITTED YOUR GUESS.**",crimePrivateRows(g,ctx.privateState));
  if(!g.playerGuesses)g.playerGuesses={};if(!g.playerIncorrectAccusations)g.playerIncorrectAccusations={};
  g.playerGuesses[u.id]=suspectId;
  const correct=suspectId===g.culpritId;
  if(!correct){g.playerIncorrectAccusations[u.id]=Number(g.playerIncorrectAccusations[u.id]||0)+1;g.incorrectAccusations++;g.perfect=false;}
  const totalPlayers=Object.keys(g.players||{}).length;
  const submitted=Object.keys(g.playerGuesses).length;
  if(submitted<totalPlayers){
    await saveCrimeGame(env,interaction.guild_id,g);
    return sendText(env,interaction,`🗳️ **GUESS LOCKED IN.**\n\nYour guess: **${g.suspects.find(s=>s.id===suspectId)?.name||"Unknown"}**\n${correct?"🟢 Your guess is correct!":"🔴 Your guess is not correct."}\n\n⏳ **${submitted}/${totalPlayers} detectives have submitted a guess.**\n\nYour guess is private until the case closes.`,crimePrivateRows(g,ctx.privateState));
  }

  g.status="solved";
  const results=[];
  for(const uid of Object.keys(g.players||{})){
    const pl=await getPlayer(env,uid);
    const playerCorrect=g.playerGuesses[uid]===g.culpritId;
    const playerState=g.privateInvestigations?.[uid]||{discovered:[],interrogated:[],contradictions:[]};const r=await crimeSavePlayerResult(env,pl,g,"multi",playerState.discovered.length>=g.evidence.length,playerCorrect,playerState);
    results.push(`${playerCorrect?"🟢":"🔴"} <@${uid}> — **${g.suspects.find(s=>s.id===g.playerGuesses[uid])?.name||"Unknown"}** ${playerCorrect?`(+${r.reward.toLocaleString()} ✨)`:"(incorrect)"}`);
  }
  await saveCrimeGame(env,interaction.guild_id,g);
  const culprit=g.suspects.find(s=>s.id===g.culpritId),acc=g.accompliceId?g.suspects.find(s=>s.id===g.accompliceId):null;
  const ending=[`🧑‍⚖️ **CASE CLOSED — ${g.name}**`,"",`🚨 **THIEF:** ${culprit.emoji} **${culprit.name}**`,g.accompliceId?`🤝 **ACCOMPLICE:** ${acc?.emoji} **${acc?.name}**`:"🤝 **ACCOMPLICE:** None",`🔐 **METHOD:** ${g.method}`,`🎭 **MOTIVE:** They ${g.motive}.`,`🧩 **CASE TYPE:** ${g.typeName}`,`🧠 **THE TWIST:** ${g.twist}`,"",`💰 **${Number(g.stolen).toLocaleString()} ✨ recovered!**`,"",`🕵️ **DETECTIVE GUESSES**`,results.join("\n")].join("\n");
  await sendChannelMessage(env,interaction.channel_id,ending,[row(button("🔎 New Multiplayer Case","crime:create",2),button("🔎 New Solo Case","crime:solo:new",1))]);
  return sendText(env,interaction,"🧑‍⚖️ **CASE CLOSED!**\n\nThe full results have been posted publicly in the case channel.",[]);
}
async function handleCrimeAccompliceMenu(env,interaction,gameId){const ctx=await getCrimePrivateGame(env,interaction,gameId);if(!ctx)return sendText(env,interaction,"❌ No active case.");if(!ctx.game.accompliceId)return sendText(env,interaction,"🧹 This case has no accomplice.");await sendText(env,interaction,"🤝 **WHO WAS THE ACCOMPLICE?**",crimeAccompliceRows(ctx.game));}
async function handleCrimeAccomplicePick(env,interaction,gameId,suspectId){const ctx=await getCrimePrivateGame(env,interaction,gameId);if(!ctx)return sendText(env,interaction,"❌ No active case.");if(!ctx.game.accompliceGuesses)ctx.game.accompliceGuesses={};ctx.game.accompliceGuesses[getUserFromInteraction(interaction)?.id]=suspectId;ctx.game.accompliceGuess=suspectId;if(ctx.mode==="multi")await saveCrimeGame(env,interaction.guild_id,ctx.game);else await savePlayer(env,ctx.player);return sendText(env,interaction,suspectId===ctx.game.accompliceId?"🤝 **CORRECT!** You identified the accomplice.":"❌ **Not the accomplice.** Keep investigating.",crimePrivateRows(ctx.game,ctx.privateState));}
async function handleSparkleCrimeCommand(env,interaction){
  const sub=interaction.data?.options?.find(o=>o.type===1)?.name||"solo";
  const u=getUserFromInteraction(interaction);
  if(sub==="solo")return handleCrimeSoloStart(env,interaction);
  if(sub==="create")return handleCrimeCreate(env,interaction);
  if(sub==="solo-status"){
    if(!u)return;
    const p=await getPlayer(env,u.id),g=p.sparkleCrimeSolo;
    if(!g||g.status!=="playing")return sendText(env,interaction,"🔎 You do not have an active solo detective case. Use `/sparklecrime solo` to open one.");
    return sendText(env,interaction,crimeCaseText(g,true),crimePrivateRows(g,ctx.privateState));
  }
  if(sub==="solo-end"){
    if(!u)return;
    const p=await getPlayer(env,u.id);
    if(!p.sparkleCrimeSolo||p.sparkleCrimeSolo.status!=="playing")return sendText(env,interaction,"🔎 You do not have an active solo detective case.");
    const caseName=p.sparkleCrimeSolo.name;
    p.sparkleCrimeSolo=null;
    await savePlayer(env,p);
    return sendText(env,interaction,`🗑️ **Solo detective case abandoned.**\n\n📁 **${caseName}** has been closed. No reward was given.`);
  }
  if(sub==="status"){
    if(u){
      const p=await getPlayer(env,u.id);
      const solo=p.sparkleCrimeSolo;
      if(solo&&solo.status==="playing")return sendText(env,interaction,crimeCaseText(solo,true),crimePrivateRows(solo));
    }
    const g=await getCrimeGame(env,interaction.guild_id);
    return g?sendText(env,interaction,crimeCaseText(g,false),crimePublicRows(g)):sendText(env,interaction,"🔎 No active Sparkle Crime case. Use `/sparklecrime solo` or `/sparklecrime create`." );
  }
  if(sub==="end"){
    if(u){
      const p=await getPlayer(env,u.id);
      if(p.sparkleCrimeSolo&&p.sparkleCrimeSolo.status==="playing"){
        const caseName=p.sparkleCrimeSolo.name;
        p.sparkleCrimeSolo=null;
        await savePlayer(env,p);
        return sendText(env,interaction,`🗑️ **Solo detective case abandoned.**\n\n📁 **${caseName}** has been closed. No reward was given.`);
      }
    }
    const g=await getCrimeGame(env,interaction.guild_id);
    if(!g)return sendText(env,interaction,"❌ No active Sparkle Crime case to end.");
    if(g.ownerId!==u?.id&&u?.id!==env.OWNER_ID)return sendText(env,interaction,"❌ Only the case host or bot owner can end the multiplayer case.");
    g.status="ended";await saveCrimeGame(env,interaction.guild_id,g);return sendText(env,interaction,"🛑 **Sparkle Crime multiplayer case ended.**");
  }
  if(sub==="leaderboard"){let b=[];try{b=JSON.parse(await env.TREE_DATA.get("sparklecrime:leaderboard")||"[]")}catch{};b=Array.isArray(b)?b:[];return sendText(env,interaction,`🏆 **SPARKLE CRIME LEADERBOARD**\n\n${b.length?b.map((x,i)=>`${i+1}. **${x.name}** — ${Number(x.reward).toLocaleString()} ✨ — ${x.caseName}`).join("\n"):"No solved cases yet."}`);}
}
