/* =========================================================
   HALLOWEEN BOOK — DIRECT PNG COMPOSITE
   Artwork is centered inside each ornate frame.
   The collectible name is rendered bold inside the plaque below.
========================================================= */
const HALLOWEEN_BOOK_SLOT_LAYOUT = [
  // Match the original full-size artwork/plaque alignment.
  { left: 0.17, top: 0.29, width: 0.285, height: 0.32, labelLeft: 0.19, labelTop: 0.64, labelWidth: 0.27, labelHeight: 0.08 },
  { left: 0.558, top: 0.29, width: 0.285, height: 0.32, labelLeft: 0.58, labelTop: 0.64, labelWidth: 0.27, labelHeight: 0.08 }
];

function halloweenBookLabelText(item, owned) {
  if (!item) return "COMING SOON";
  if (!owned || !owned.has(item.id)) return "COMING SOON";
  const labels = {
    hunters_lantern: "HUNTER'S LANTERN",
    last_antidote: "LAST ANTIDOTE",
    cursed_candy_bucket: "CURSED CANDY BUCKET",
    smasher_relic: "SMASHER'S RELIC",
    grave_mask: "GRAVE MASK",
    phantom_compass: "PHANTOM COMPASS",
    zombie_brain: "ZOMBIE BRAIN"
  };
  return labels[item.id] || String(item.title || "COLLECTIBLE").replace(/[^A-Za-z0-9 ]+/g, "").trim().toUpperCase();
}

function drawHalloweenBookLabel(frame, item, owned, box) {
  const text = halloweenBookLabelText(item, owned);
  const maxWidth = Math.max(1, Math.round(frame.width * box.labelWidth));
  const labelHeight = Math.max(12, Math.round(frame.height * box.labelHeight));
  const preferredScale = 3;
  const widthAtScale = scale => [...text].reduce((n, ch) => n + (ch === " " ? 3 * scale : 6 * scale), 0) - scale;
  const scale = widthAtScale(preferredScale) <= maxWidth ? preferredScale : 2;
  const textWidth = widthAtScale(scale);
  const x = Math.round(frame.width * box.labelLeft + Math.max(0, (maxWidth - textWidth) / 2));
  const y = Math.round(frame.height * box.labelTop + Math.max(0, (labelHeight - 7 * scale) / 2));

  // The plaque is already part of the book artwork. Print the title directly
  // inside it, matching the desired physical-book look.
  drawBitmapText(frame, text, x + 1, y + 1, scale, [118, 78, 50], maxWidth);
  drawBitmapText(frame, text, x, y, scale, [55, 38, 28], maxWidth);
}

async function renderHalloweenBookDirect(env, player, spread) {
  const s = Math.max(0, Math.min(4, Number(spread) || 0));
  const collection = halloweenBookCollectionConfig();
  const owned = new Set(Array.isArray(player?.halloweenCollection) ? player.halloweenCollection : []);
  const base = await getPngAsset(env, IMAGES.halloweenBookPages);
  if (!base) throw new Error("Halloween book page asset is missing.");
  const scene = { width: base.width, height: base.height, data: new Uint8Array(base.data) };
  scene.data.set(base.data);
  const firstIndex = s * 2;

  for (let slot = 0; slot < 2; slot++) {
    const item = collection[firstIndex + slot];
    const box = HALLOWEEN_BOOK_SLOT_LAYOUT[slot];
    if (!item || !owned.has(item.id) || !item.imageKey) {
      drawHalloweenBookLabel(scene, item, owned, box);
      continue;
    }
    try {
      const asset = await getPngAsset(env, IMAGES[item.imageKey]);
      if (!asset) { drawHalloweenBookLabel(scene, item, owned, box); continue; }
      const boxWidth = Math.max(1, Math.round(scene.width * box.width));
      const boxHeight = Math.max(1, Math.round(scene.height * box.height));
      const layer = containRGBA(asset, boxWidth, boxHeight);
      const x = Math.round(scene.width * box.left + (boxWidth - layer.width) / 2);
      const y = Math.round(scene.height * box.top + (boxHeight - layer.height) / 2);
      alphaComposite(scene, layer, x, y, 1);
      drawHalloweenBookLabel(scene, item, owned, box);
    } catch (error) {
      console.warn(`Halloween collectible render skipped for ${item.id}:`, error?.message || error);
    }
  }
  return rgbaToRgbPng(scene);
}

async function sendHalloweenBook(env, interaction, spread=0) {
  const user = getUserFromInteraction(interaction);
  if (!user) return sendText(env, interaction, "❌ I couldn't identify your account.");
  const player = await getPlayer(env, user.id);
  const s = Math.max(0, Math.min(4, Number(spread) || 0));
  try {
    const rendered = await renderHalloweenBookDirect(env, player, s);
    const payload = halloweenBookData(player, s, "attachment://halloween-book.png");
    const form = new FormData();
    form.append("payload_json", JSON.stringify({ content: payload.content, embeds: payload.embeds, components: payload.components, attachments: [{ id: 0, filename: "halloween-book.png" }], flags: 64 }));
    form.append("files[0]", new Blob([rendered], { type: "image/png" }), "halloween-book.png");
    const response = await fetch(`https://discord.com/api/v10/webhooks/${env.CLIENT_ID}/${interaction.token}/messages/@original`, { method: "PATCH", body: form });
    if (!response.ok) {
      console.error("Halloween book image update failed:", response.status, await response.text());
      return editOriginalResponse(env, interaction, halloweenBookData(player, s));
    }
    return response;
  } catch (error) {
    console.error("Halloween direct book render failed:", error);
    return editOriginalResponse(env, interaction, halloweenBookData(player, s));
  }
}


/* =========================================================
   SPOOK N SMASH — SOLO HALLOWEEN ARCADE GAME
   60-second reaction game. The board updates automatically;
   button presses only resolve the creature currently in that hole.
========================================================= */
const SPOOK_SMASH_DURATION = 60 * 1000;
const SPOOK_SMASH_GAME_PREFIX = "halloween:spook:game:";

const SPOOK_SMASH_CREATURES = {
  ghost:   { emoji: "👻", name: "Ghost", points: 100, hits: 1, style: 1 },
  pumpkin:{ emoji: "🎃", name: "Pumpkin", points: 75, hits: 1, style: 1 },
  spider: { emoji: "🕷️", name: "Spider", points: 250, hits: 2, style: 3 },
  bat:    { emoji: "🦇", name: "Bat", points: 175, hits: 1, style: 3 },
  witch:  { emoji: "🧙", name: "Witch", points: 300, hits: 1, style: 3 },
  golden: { emoji: "✨🎃", name: "Golden Pumpkin", points: 500, hits: 1, style: 3 },
  skull:  { emoji: "💀", name: "Skull", points: -200, hits: 1, style: 4 }
};

function spookSmashKey(guildId, userId) {
  return `halloween:spooksmash:${guildId}:${userId}`;
}
function spookSmashBoardKey(guildId, userId) {
  return `halloween:spooksmash:board:${guildId}:${userId}`;
}

function spookSmashWave(elapsed) {
  const second = Math.floor(Math.max(0, elapsed) / 1000);
  if (second < 8) return 1;
  if (second < 16) return 2;
  if (second < 25) return 3;
  if (second < 35) return 4;
  if (second < 46) return 5;
  if (second < 54) return 6;
  return 7;
}

function spookSmashWindowMs(wave) {
  if (wave <= 1) return 1900;
  if (wave <= 3) return 1600;
  if (wave <= 5) return 1400;
  if (wave === 6) return 1200;
  return 1000;
}

function spookSmashAllowed(wave) {
  if (wave === 1) return ["ghost", "pumpkin"];
  if (wave === 2) return ["ghost", "pumpkin", "spider"];
  if (wave === 3) return ["ghost", "pumpkin", "spider", "bat"];
  if (wave === 4) return ["ghost", "pumpkin", "spider", "bat", "skull"];
  if (wave === 5) return ["ghost", "pumpkin", "spider", "bat", "skull", "witch"];
  if (wave === 6) return ["ghost", "pumpkin", "spider", "bat", "skull", "witch", "golden"];
  return ["ghost", "pumpkin", "spider", "bat", "skull", "witch", "golden"];
}

function spookSmashPickCreature(wave) {
  const pool = spookSmashAllowed(wave);
  const weights = {
    ghost: 32, pumpkin: 28, spider: 13, bat: 10,
    skull: wave >= 4 ? 8 : 0,
    witch: wave >= 5 ? 6 : 0,
    golden: wave >= 6 ? 3 : 0
  };
  const weighted = [];
  for (const id of pool) {
    for (let i = 0; i < (weights[id] || 1); i++) weighted.push(id);
  }
  return weighted[randomInt(0, weighted.length - 1)] || "ghost";
}

function spookSmashMakeBoard(wave) {
  const board = Array.from({ length: 12 }, () => null);
  const count = wave <= 2 ? randomInt(1, 3) : wave <= 4 ? randomInt(2, 4) : randomInt(2, 5);
  const positions = [];
  while (positions.length < count) {
    const p = randomInt(0, 11);
    if (!positions.includes(p)) positions.push(p);
  }
  for (const position of positions) {
    const type = spookSmashPickCreature(wave);
    board[position] = {
      type,
      glowing: type === "witch" ? Math.random() < 0.55 : false,
      hits: 0,
      spawnedAt: Date.now(),
      expiresAt: Date.now() + spookSmashWindowMs(wave)
    };
  }
  return board;
}

function spookSmashComboMultiplier(combo) {
  if (combo >= 30) return 5;
  if (combo >= 20) return 4;
  if (combo >= 10) return 3;
  if (combo >= 5) return 2;
  return 1;
}

function spookSmashWaveName(wave) {
  return ({
    1: "TRICK OR TREAT",
    2: "SOMETHING CRAWLING",
    3: "BATS!",
    4: "DON'T TOUCH THAT",
    5: "WITCHING HOUR",
    6: "JACKPOT",
    7: "TOTAL CHAOS"
  })[wave] || "TOTAL CHAOS";
}

function spookSmashHowToText() {
  return [
    "📖🎃 **SPOOK N SMASH — HOW TO PLAY** 🎃📖",
    "",
    "⏱️ **You have 60 seconds.** Smash the right creatures as they appear.",
    "The board changes **automatically**, so keep watching the holes! 👀",
    "",
    "👻 **Ghost** — +100",
    "🎃 **Pumpkin** — +75",
    "🕷️ **Spider** — +250 (smash twice quickly)",
    "🦇 **Bat** — +175 (catch it before it moves)",
    "🧙 **Glowing Witch** — +300",
    "✨🎃 **Golden Pumpkin** — +500",
    "💀 **SKULL — DO NOT SMASH** — −200 + combo reset",
    "",
    "🔥 **COMBO:** 5 = x2 • 10 = x3 • 20 = x4 • 30 = x5",
    "❌ Missing a normal creature is safe — it just escapes.",
    "💀 Hitting a Skull or missing a special target breaks your combo.",
    "",
    "🧠 **Watch. Decide. SMASH.** Good luck. 😈"
  ].join("\n");
}

function spookSmashComponents(g) {
  const board = Array.isArray(g?.board) ? g.board : Array(12).fill(null);
  const rows = [];
  // The 12 Discord buttons ARE the game board. No generated images are used.
  for (let i = 0; i < 12; i += 4) {
    rows.push(row(...[i, i + 1, i + 2, i + 3].map(index => {
      const target = board[index];
      if (!target) return button("🕳️", `halloween:spook:${g.session}:${index}`, 2);
      const c = SPOOK_SMASH_CREATURES[target.type] || SPOOK_SMASH_CREATURES.ghost;
      const label = target.type === "witch" && target.glowing ? "✨🧙" : c.emoji;
      return button(label, `halloween:spook:${g.session}:${index}`, c.style);
    })));
  }
  rows.push(row(
    button("📖 HOW TO PLAY", `halloween:spook:howto:${g.session}`, 2),
    button("🏁 END RUN", `halloween:spook:end:${g.session}`, 4),
    button("🏠 HALLOWEEN GAMES", "halloween:games", 2)
  ));
  return rows;
}

function spookSmashText(g, now = Date.now()) {
  const remaining = Math.max(0, Number(g.endAt || 0) - now);
  const seconds = Math.ceil(remaining / 1000);
  const mult = spookSmashComboMultiplier(Number(g.combo || 0));
  return [
    "🎃💥 **SPOOK N SMASH** 💥🎃",
    "",
    `⏱️ **${seconds}s**   •   🌊 **Wave ${g.wave || 1}: ${spookSmashWaveName(g.wave || 1)}**`,
    `🏆 **Score:** ${Number(g.score || 0).toLocaleString()}   •   🔥 **Combo:** ${Number(g.combo || 0)}   **x${mult}**`,
    "",
    "👆 **SMASH THE CREATURES!**",
    "The 4×3 buttons below are the 12 holes. Click the creature currently in that hole.",
    "",
    `👻 ${g.stats?.ghosts || 0}  🎃 ${g.stats?.pumpkins || 0}  ✨🎃 ${g.stats?.goldens || 0}  💀 ${g.stats?.skulls || 0}`
  ].join("\n");
}

function spookSmashData(g, now = Date.now()) {
  return {
    content: spookSmashText(g, now),
    embeds: [],
    components: spookSmashComponents(g)
  };
}

async function editSpookSmashBoard(env, interaction, g, now = Date.now()) {
  // Spook N Smash is intentionally image-free. The 12 Discord buttons are the board.
  return editOriginalResponse(env, interaction, spookSmashData(g, now));
}

function spookSmashFinalData(g) {
  const score = Number(g.score || 0);
  const bestCombo = Number(g.bestCombo || 0);
  return {
    content: [
      "🎃💥 **SPOOK N SMASH — GAME OVER!** 💥🎃",
      "",
      `🏆 **Score:** ${score.toLocaleString()}`,
      `🔥 **Best Combo:** ${bestCombo}`,
      `👻 **Ghosts:** ${g.stats?.ghosts || 0}`,
      `🎃 **Pumpkins:** ${g.stats?.pumpkins || 0}`,
      `✨🎃 **Golden Pumpkins:** ${g.stats?.goldens || 0}`,
      `💀 **Skulls Hit:** ${g.stats?.skulls || 0}`,
      `💰 **Spookies Earned:** ${Number(g.reward || 0).toLocaleString()}`,
      g.newBest ? "\n🏅 **NEW PERSONAL BEST!**" : "",
      "",
      "Ready to smash some more? 😈"
    ].join("\n"),
    components: [
      row(button("🔄 PLAY AGAIN", "halloween:start:spook", 1), button("🏠 HALLOWEEN GAMES", "halloween:games", 2))
    ]
  };
}

function spookSmashReward(score, g = {}) {
  let reward = score >= 15000 ? 100 : score >= 10000 ? 80 : score >= 7500 ? 60 : score >= 5000 ? 45 : score >= 2500 ? 30 : score >= 1000 ? 20 : 10;
  const best = Number(g.bestCombo || 0);
  if (best >= 20) reward += 10;
  if (best >= 30) reward += 15;
  if (best >= 40) reward += 20;
  reward += Number(g.stats?.goldens || 0) * 5;
  if (Number(g.stats?.skulls || 0) === 0) reward += 10;
  return Math.min(150, reward);
}

async function spookSmashLoad(env, guildId, userId) {
  const raw = await env.TREE_DATA.get(spookSmashKey(guildId, userId));
  if (!raw) return null;
  try { return JSON.parse(raw); } catch { return null; }
}
async function spookSmashSave(env, guildId, userId, game) {
  await env.TREE_DATA.put(spookSmashKey(guildId, userId), JSON.stringify(game));
}
async function spookSmashLoadBoard(env, guildId, userId) {
  const raw = await env.TREE_DATA.get(spookSmashBoardKey(guildId, userId));
  if (!raw) return null;
  try { return JSON.parse(raw); } catch { return null; }
}
async function spookSmashSaveBoard(env, guildId, userId, board) {
  await env.TREE_DATA.put(spookSmashBoardKey(guildId, userId), JSON.stringify(board));
}

async function spookSmashHowTo(env, interaction, session) {
  const rows = [
    row(button("🔙 BACK TO GAME", `halloween:spook:back:${session}`, 2))
  ];
  return editOriginalResponse(env, interaction, { content: spookSmashHowToText(), embeds: [], components: rows });
}

async function spookSmashFinish(env, interaction, g) {
  if (!g || !g.active) return;
  g.active = false;
  g.finishedAt = Date.now();
  g.reward = spookSmashReward(Number(g.score || 0), g);
  const p = await getPlayer(env, g.userId);
  const oldBest = Number(p.halloweenSpookSmashBest || 0);
  g.newBest = Number(g.score || 0) > oldBest;
  p.halloweenSpookSmashBest = Math.max(oldBest, Number(g.score || 0));
  p.halloweenSpookSmashRuns = Number(p.halloweenSpookSmashRuns || 0) + 1;
  p.halloweenSpookies = Math.max(0, Number(p.halloweenSpookies || 0) + g.reward);
  p.halloweenGamesPlayed = Number(p.halloweenGamesPlayed || 0) + 1;
  refreshProfileBadges(p);
  await savePlayer(env, p, g.userId, { skipRaccoonEmpireBonus: true, skipSparkleMagnet: true });
  await spookSmashSave(env, g.guildId, g.userId, g);
  await env.TREE_DATA.delete(spookSmashBoardKey(g.guildId, g.userId));
  await editOriginalResponse(env, interaction, spookSmashFinalData(g));
}

async function startSpookSmash(env, interaction, ctx = null) {
  const user = getUserFromInteraction(interaction);
  const guildId = interaction.guild_id;
  if (!user || !guildId) return sendText(env, interaction, "❌ Spook N Smash can only be played inside a server.");

  const existing = await spookSmashLoad(env, guildId, user.id);
  if (existing?.active && Number(existing.endAt || 0) > Date.now()) {
    const board = await spookSmashLoadBoard(env, guildId, user.id);
    return editOriginalResponse(env, interaction, spookSmashData({...existing, board}, Date.now()));
  }

  const session = `${Date.now().toString(36)}${randomInt(1000,9999)}`;
  const startedAt = Date.now();
  const g = {
    active: true,
    session,
    guildId,
    userId: user.id,
    startedAt,
    endAt: startedAt + SPOOK_SMASH_DURATION,
    wave: 1,
    score: 0,
    combo: 0,
    bestCombo: 0,
    reward: 0,
    stats: { ghosts: 0, pumpkins: 0, goldens: 0, skulls: 0 },
    lastHitAt: 0,
    interactionToken: interaction.token
  };

  const board = spookSmashMakeBoard(1);
  await spookSmashSave(env, guildId, user.id, g);
  await spookSmashSaveBoard(env, guildId, user.id, board);

  // No timers, Puppeteer, image uploads, or background message loops.
  // The game advances safely whenever the player presses a button.
  return editSpookSmashBoard(env, interaction, {...g, board}, Date.now());
}

async function spookSmashAdvanceBoard(env, guildId, userId, g) {
  const elapsed = Date.now() - Number(g.startedAt || Date.now());
  g.wave = spookSmashWave(elapsed);
  const board = spookSmashMakeBoard(g.wave);
  await spookSmashSaveBoard(env, guildId, userId, board);
  await spookSmashSave(env, guildId, userId, g);
  return board;
}

async function spookSmashClick(env, interaction, session, index) {
  const user = getUserFromInteraction(interaction);
  const guildId = interaction.guild_id;
  const g = await spookSmashLoad(env, guildId, user.id);
  if (!g || !g.active || g.session !== session) {
    return sendEphemeralFollowup(env, interaction, "🎃 That Spook N Smash run is no longer active.");
  }

  const now = Date.now();
  if (now >= Number(g.endAt || 0)) {
    await spookSmashFinish(env, interaction, g);
    return;
  }

  const board = await spookSmashLoadBoard(env, guildId, user.id);
  const slot = Number(index);
  if (!Number.isInteger(slot) || slot < 0 || slot > 11) {
    return sendEphemeralFollowup(env, interaction, "❌ Invalid hole.");
  }

  const target = Array.isArray(board) ? board[slot] : null;
  if (!target) {
    const nextBoard = await spookSmashAdvanceBoard(env, guildId, user.id, g);
    await editSpookSmashBoard(env, interaction, {...g, board: nextBoard}, Date.now());
    return sendEphemeralFollowup(env, interaction, "🕳️ **WHIFF!** Nothing was there! No penalty. 👻");
  }

  const creature = SPOOK_SMASH_CREATURES[target.type] || SPOOK_SMASH_CREATURES.ghost;
  target.hits = Number(target.hits || 0) + 1;

  if (target.type === "skull") {
    g.score = Math.max(0, Number(g.score || 0) - 200);
    g.combo = 0;
    g.stats.skulls = Number(g.stats.skulls || 0) + 1;
    board[slot] = null;
    await spookSmashSaveBoard(env, guildId, user.id, board);
    await spookSmashSave(env, guildId, user.id, g);
    const nextBoard = await spookSmashAdvanceBoard(env, guildId, user.id, g);
    await editSpookSmashBoard(env, interaction, {...g, board: nextBoard}, Date.now());
    return sendEphemeralFollowup(env, interaction, "💀 **CURSED!** −200 points and your combo is gone! DO NOT SMASH THE SKULL 😭");
  }

  const required = Number(creature.hits || 1);
  if (target.hits < required) {
    board[slot] = target;
    await spookSmashSaveBoard(env, guildId, user.id, board);
    await spookSmashSave(env, guildId, user.id, g);
    await editSpookSmashBoard(env, interaction, {...g, board}, Date.now());
    return sendEphemeralFollowup(env, interaction, "🕷️ **HIT!** One more! QUICK! ⚡");
  }

  if (target.type === "witch" && !target.glowing) {
    g.combo = 0;
    board[slot] = null;
    await spookSmashSaveBoard(env, guildId, user.id, board);
    await spookSmashSave(env, guildId, user.id, g);
    const nextBoard = await spookSmashAdvanceBoard(env, guildId, user.id, g);
    await editSpookSmashBoard(env, interaction, {...g, board: nextBoard}, Date.now());
    return sendEphemeralFollowup(env, interaction, "🧙 **NOT GLOWING!** The witch cursed your combo. 😭");
  }

  g.combo = Number(g.combo || 0) + 1;
  g.bestCombo = Math.max(Number(g.bestCombo || 0), g.combo);
  const mult = spookSmashComboMultiplier(g.combo);
  g.score = Math.max(0, Number(g.score || 0) + creature.points * mult);
  if (target.type === "ghost") g.stats.ghosts++;
  if (target.type === "pumpkin") g.stats.pumpkins++;
  if (target.type === "golden") g.stats.goldens++;

  // COLLECTIBLE #4 — THE SMASHER'S RELIC
  // The player must reach Wave 6: JACKPOT, successfully smash a Golden
  // Pumpkin, and have never hit a Skull during that run.
  let smasherRelicUnlocked = false;
  const currentWave = spookSmashWave(Date.now() - Number(g.startedAt || Date.now()));
  if (target.type === "golden" && currentWave >= 6 && Number(g.stats.skulls || 0) === 0) {
    const playerForCollection = await getPlayer(env, user.id);
    playerForCollection.halloweenCollection = Array.isArray(playerForCollection.halloweenCollection) ? playerForCollection.halloweenCollection : [];
    if (!playerForCollection.halloweenCollection.includes("smasher_relic")) {
      playerForCollection.halloweenCollection.push("smasher_relic");
      smasherRelicUnlocked = true;
      refreshProfileBadges(playerForCollection);
      await savePlayer(env, playerForCollection, user.id, { skipRaccoonEmpireBonus: true, skipSparkleMagnet: true });
    }
  }

  board[slot] = null;

  await spookSmashSaveBoard(env, guildId, user.id, board);
  await spookSmashSave(env, guildId, user.id, g);
  const nextBoard = await spookSmashAdvanceBoard(env, guildId, user.id, g);
  await editSpookSmashBoard(env, interaction, {...g, board: nextBoard}, Date.now());

  const hit = target.type === "golden" ? "✨🎃 **JACKPOT!**" : `${creature.emoji} **SMASHED!**`;

  if (smasherRelicUnlocked) {
    const unlockResponse = await fetch(
      `https://discord.com/api/v10/webhooks/${env.CLIENT_ID}/${interaction.token}`,
      {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          content: "🔨✨ **THE GOLDEN SMASH!** ✨🔨\n\nThe Golden Pumpkin shattered... but something else was hiding inside.",
          embeds: [{
            title: "📖✨ COLLECTIBLE #4 UNLOCKED! ✨📖",
            description: "🔨 **The Smasher's Relic**\n\n*They say the first Spook N Smash champion wielded this very hammer.*\n\n🎃 **Wave 6: JACKPOT**\n💀 **No Skulls hit**\n✨ **Golden Pumpkin smashed**",
            color: 0x8b3a12,
            image: { url: imageUrl(IMAGES[HALLOWEEN_BOOK_ASSETS.smasherRelic]) },
            footer: { text: "WereWives Halloween 2026 • Permanent Collection" }
          }]
        })
      }
    );
    if (!unlockResponse.ok) console.error("Smasher's Relic unlock announcement failed:", unlockResponse.status, await unlockResponse.text());
  }

  return sendEphemeralFollowup(env, interaction, `${hit} **+${(creature.points * mult).toLocaleString()}** • Combo **${g.combo}** x${mult}${smasherRelicUnlocked ? "\n\n🔨✨ **THE SMASHER'S RELIC UNLOCKED!** Check your Halloween Collection!" : ""}`);
}

async function spookSmashEndRun(env, interaction, session) {
  const user = getUserFromInteraction(interaction);
  const g = await spookSmashLoad(env, interaction.guild_id, user.id);
  if (!g || !g.active || g.session !== session) {
    return sendEphemeralFollowup(env, interaction, "🎃 That Spook N Smash run is no longer active.");
  }
  await spookSmashFinish(env, interaction, g);
}

function halloweenHowToText() {
  return [
    "📖 **HOW HALLOWEEN WORKS**",
    "",
    "👻 **Spookies** are the Halloween currency.",
    "🎮 Play the Halloween games to earn them.",
    "🎁 Claim one Daily Reward every day and build your streak.",
    "🏆 The Leaderboard ranks players by Spookies.",
    "📚 Your collectibles are permanent and live in `/collections`.",
    "",
    "🔒 Each game has its own collectible with a specific unlock requirement.",
    "🧠 Haunted Trivia has 15 randomized challenges, including special rounds that are not normal questions.",
    "",
    "🆘 If you ever get trapped in a Halloween game, use **/halloween end**."
  ].join("\n");
}

async function addHalloweenSpookies(env,userId,amount) {
  const p=await getPlayer(env,userId); p.halloweenSpookies=Math.max(0,Number(p.halloweenSpookies||0)+Number(amount||0)); await savePlayer(env,p,userId,{skipRaccoonEmpireBonus:true,skipSparkleMagnet:true}); return p;
}
async function halloweenMarkPlayed(env,userId,amount=1) {
  const p=await getPlayer(env,userId); p.halloweenGamesPlayed=Number(p.halloweenGamesPlayed||0)+amount; refreshProfileBadges(p); await savePlayer(env,p,userId,{skipRaccoonEmpireBonus:true,skipSparkleMagnet:true}); return p;
}
async function halloweenUnlock(env,userId,id) {
  const p=await getPlayer(env,userId); p.halloweenCollection=Array.isArray(p.halloweenCollection)?p.halloweenCollection:[]; if(!p.halloweenCollection.includes(id)) p.halloweenCollection.push(id);
  if(p.halloweenCollection.length>=10) unlockOwnedTitle(p,"keeper_of_halloween"); refreshProfileBadges(p); await savePlayer(env,p,userId,{skipRaccoonEmpireBonus:true,skipSparkleMagnet:true}); return p;
}

async function halloweenDaily(env,interaction) {
  const user=getUserFromInteraction(interaction); if(!user)return sendText(env,interaction,"❌ I couldn't identify your account.");
  const p=await getPlayer(env,user.id); const today=easternDateKey();
  if(p.halloweenDailyDate===today) return sendText(env,interaction,`🎁 **DAILY REWARD ALREADY CLAIMED!**\n\n🔥 Streak: **${Number(p.halloweenDailyStreak||1)} day(s)**\n👻 Spookies: **${Number(p.halloweenSpookies||0).toLocaleString()}**\n\nCome back tomorrow! 🎃` , [row(button("⬅️ Halloween Hub","halloween:hub",2))]);
  const yesterday=easternDateKey(new Date(Date.now()-24*60*60*1000));
  p.halloweenDailyStreak=p.halloweenDailyDate===yesterday?Number(p.halloweenDailyStreak||0)+1:1;
  const rewards=[100,125,150,175,200,250,300]; const reward=rewards[Math.min(p.halloweenDailyStreak-1,rewards.length-1)];
  p.halloweenDailyDate=today; p.halloweenSpookies=Number(p.halloweenSpookies||0)+reward; refreshProfileBadges(p); await savePlayer(env,p,user.id,{skipRaccoonEmpireBonus:true,skipSparkleMagnet:true});
  return sendText(env,interaction,`🎁 **HALLOWEEN DAILY REWARD!**\n\n👻 You received **+${reward} Spookies**!\n🔥 Streak: **${p.halloweenDailyStreak} day(s)**\n👻 Balance: **${p.halloweenSpookies.toLocaleString()} Spookies**\n\nKeep the streak alive tomorrow! 🕷️`,[row(button("⬅️ Halloween Hub","halloween:hub",2))]);
}

async function halloweenLeaderboard(env,interaction) {
  const keys=await listAllPlayerKeys(env); const players=[];
  for(const key of keys){const p=await getPlayer(env,key); if(Number(p.halloweenSpookies||0)>0||Number(p.halloweenGamesPlayed||0)>0)players.push(p);}
  players.sort((a,b)=>Number(b.halloweenSpookies||0)-Number(a.halloweenSpookies||0));
  const top=players.slice(0,10); if(!top.length)return sendText(env,interaction,"🏆 **HALLOWEEN LEADERBOARD**\n\nNobody has earned Spookies yet! Be the first! 👻");
  const lines=top.map((p,i)=>`**${i+1}.** ${getDisplayName(p)} — 👻 **${Number(p.halloweenSpookies||0).toLocaleString()} Spookies**`);
  return sendText(env,interaction,`🏆🎃 **HALLOWEEN 2026 LEADERBOARD**\n\n${lines.join("\n")}`,[row(button("⬅️ Halloween Hub","halloween:hub",2))]);
}

function halloweenNewGameBlocked(state){return state.halloween?.activeGame?.status && state.halloween.activeGame.status!=="ended";}

/* =========================================================
   HAUNTED MAZE — SOLO TEXT-MOVEMENT HALLOWEEN GAME
========================================================= */
const HALLOWEEN_MAZE_SIZE=11;
const HALLOWEEN_MAZE_RELICS=[{id:"skull_key",emoji:"🗝️",name:"Skeleton Key"},{id:"ghost_gem",emoji:"💎",name:"Ghost Gem"},{id:"cursed_pumpkin",emoji:"🎃",name:"Cursed Pumpkin"}];
function halloweenMazeGenerateLayout(size=HALLOWEEN_MAZE_SIZE){const grid=Array.from({length:size},()=>Array(size).fill("#"));const stack=[[1,1]];grid[1][1]=".";while(stack.length){const [r,c]=stack[stack.length-1];const dirs=[[2,0],[-2,0],[0,2],[0,-2]];for(let i=dirs.length-1;i>0;i--){const j=randomInt(0,i);[dirs[i],dirs[j]]=[dirs[j],dirs[i]];}const pick=dirs.find(([dr,dc])=>{const nr=r+dr,nc=c+dc;return nr>0&&nr<size-1&&nc>0&&nc<size-1&&grid[nr][nc]==="#";});if(!pick){stack.pop();continue;}const [dr,dc]=pick;grid[r+dr/2][c+dc/2]=".";grid[r+dr][c+dc]=".";stack.push([r+dr,c+dc]);}grid[size-2][size-2]=".";return grid;}
function halloweenMazeWalkable(g,r,c){return !!g?.grid?.[r]?.[c]&&g.grid[r][c]===".";}
function halloweenMazeDistance(g,start,goal){const q=[[start[0],start[1],0]],seen=new Set([start.join(",")]);while(q.length){const [r,c,d]=q.shift();if(r===goal[0]&&c===goal[1])return d;for(const [dr,dc] of [[1,0],[-1,0],[0,1],[0,-1]]){const nr=r+dr,nc=c+dc,k=`${nr},${nc}`;if(!seen.has(k)&&halloweenMazeWalkable(g,nr,nc)){seen.add(k);q.push([nr,nc,d+1]);}}}return Infinity;}
function halloweenMazeReveal(g,radius=1){g.revealed=Array.isArray(g.revealed)?g.revealed:[];for(let r=0;r<HALLOWEEN_MAZE_SIZE;r++)for(let c=0;c<HALLOWEEN_MAZE_SIZE;c++)if(Math.abs(r-g.player.r)<=radius&&Math.abs(c-g.player.c)<=radius)g.revealed.push(`${r},${c}`);g.revealed=[...new Set(g.revealed)];}
function halloweenMazeVisible(g,r,c){return new Set(g.revealed||[]).has(`${r},${c}`);}
function halloweenMazeNextStep(g,from,to){
  const start=Array.isArray(from) ? [Number(from[0]),Number(from[1])] : [Number(from?.r),Number(from?.c)];
  const goal=Array.isArray(to) ? [Number(to[0]),Number(to[1])] : [Number(to?.r),Number(to?.c)];
  const startKey=`${start[0]},${start[1]}`;
  const goalKey=`${goal[0]},${goal[1]}`;
  if(startKey===goalKey)return start;
  const q=[start];
  const prev=new Map();
  prev.set(startKey,null);
  while(q.length){
    const cur=q.shift();
    const r=Number(cur[0]),c=Number(cur[1]);
    if(r===goal[0]&&c===goal[1])break;
    for(const [dr,dc] of [[1,0],[-1,0],[0,1],[0,-1]]){
      const nr=r+dr,nc=c+dc,k=`${nr},${nc}`;
      if(prev.has(k)||!halloweenMazeWalkable(g,nr,nc))continue;
      prev.set(k,[r,c]);
      q.push([nr,nc]);
    }
  }
  if(!prev.has(goalKey))return start;
  let cur=goal;
  while(true){
    const key=`${cur[0]},${cur[1]}`;
    const parent=prev.get(key);
    if(parent===null||parent===undefined)return cur;
    const parentKey=`${parent[0]},${parent[1]}`;
    if(parentKey===startKey)return cur;
    cur=parent;
  }
}
function halloweenMazeBoardText(g){const out=["🗺️ **HAUNTED MAZE**","",`❤️ **Hearts:** ${g.hearts}   🕯️ **Candles:** ${g.candles}   🧪 **Repellent:** ${g.repellents}`,`🗝️ **${g.collected.length}/3 relics found**   👣 **Moves:** ${g.moves}`,""];for(let r=0;r<HALLOWEEN_MAZE_SIZE;r++){let line="";for(let c=0;c<HALLOWEEN_MAZE_SIZE;c++){if(r===g.player.r&&c===g.player.c){line+="🙂";continue;}if(r===g.ghost.r&&c===g.ghost.c&&!g.ghostBanished){line+="👻";continue;}if(!halloweenMazeVisible(g,r,c)){line+="❓";continue;}if(r===g.exit.r&&c===g.exit.c){line+="🚪";continue;}const relic=g.relics.find(x=>!x.found&&x.r===r&&x.c===c);if(relic){line+=relic.emoji;continue;}const treasure=g.treasures.find(x=>!x.claimed&&x.r===r&&x.c===c);if(treasure){line+="💰";continue;}const trap=g.traps.find(x=>!x.triggered&&x.r===r&&x.c===c);if(trap){line+="🕸️";continue;}line+=g.grid[r][c]==="#"?"🧱":"⬜";}out.push(line);}out.push("",g.lastEvent||"🧭 Use the arrow buttons to move through the maze.");return out.join("\n");}
function halloweenMazeRows(g){
  if(g.status!=="playing") return [];
  return [
    row(button("⬆️",`halloween:maze:move:${g.id}:up`,1)),
    row(button("⬅️",`halloween:maze:move:${g.id}:left`,1),button("⬇️",`halloween:maze:move:${g.id}:down`,1),button("➡️",`halloween:maze:move:${g.id}:right`,1)),
    row(button("🕯️ LIGHT",`halloween:maze:light:${g.id}`,1),button("🧪 REPELLENT",`halloween:maze:repellent:${g.id}`,1)),
    row(button("📖 HOW TO PLAY",`halloween:maze:howto:${g.id}`,2),button("🏃 END RUN",`halloween:maze:end:${g.id}`,4))
  ];
}
function halloweenMazeCreate(guildId,user,channelId){let grid;do{grid=halloweenMazeGenerateLayout();}while(halloweenMazeDistance({grid},[1,1],[HALLOWEEN_MAZE_SIZE-2,HALLOWEEN_MAZE_SIZE-2])<12);const walk=[];for(let r=1;r<HALLOWEEN_MAZE_SIZE-1;r++)for(let c=1;c<HALLOWEEN_MAZE_SIZE-1;c++)if(grid[r][c]==="."&&!(r===1&&c===1)&&!(r===HALLOWEEN_MAZE_SIZE-2&&c===HALLOWEEN_MAZE_SIZE-2))walk.push([r,c]);for(let i=walk.length-1;i>0;i--){const j=randomInt(0,i);[walk[i],walk[j]]=[walk[j],walk[i]];}const relics=HALLOWEEN_MAZE_RELICS.map((x,i)=>({...x,r:walk[i][0],c:walk[i][1],found:false}));const treasures=walk.slice(3,5).map(([r,c])=>({r,c,claimed:false}));const trapCandidates=walk.filter(([r,c])=>{const neighbors=[[1,0],[-1,0],[0,1],[0,-1]].filter(([dr,dc])=>{const nr=r+dr,nc=c+dc;return nr>=0&&nr<HALLOWEEN_MAZE_SIZE&&nc>=0&&nc<HALLOWEEN_MAZE_SIZE&&grid[nr][nc]===".";}).length;return neighbors>=2;});for(let i=trapCandidates.length-1;i>0;i--){const j=randomInt(0,i);[trapCandidates[i],trapCandidates[j]]=[trapCandidates[j],trapCandidates[i]];}const traps=trapCandidates.slice(0,3).map(([r,c])=>({r,c,triggered:false}));const ghostCandidates=walk.filter(([r,c])=>{const d=halloweenMazeDistance({grid},[1,1],[r,c]);return d>=10&&d<=16;});const ghost=ghostCandidates.length?ghostCandidates[randomInt(0,ghostCandidates.length-1)]:walk[walk.length-1];const g={id:`mz-${Date.now().toString(36)}-${randomInt(1000,9999)}`,type:"maze",status:"playing",guildId:String(guildId),playerId:String(user.id),channelId:channelId||"",messageId:"",publicMessageId:"",grid,player:{r:1,c:1},exit:{r:HALLOWEEN_MAZE_SIZE-2,c:HALLOWEEN_MAZE_SIZE-2},ghost:{r:ghost[0],c:ghost[1]},ghostBanished:false,relics,collected:[],treasures,traps,revealed:[],hearts:3,candles:3,repellents:2,repelMoves:0,ghostStunMoves:0,moves:0,lastEvent:"🕯️ The maze closes behind you. The ghost is already hunting. Find all three relics, then escape through 🚪."};halloweenMazeReveal(g,1);return g;}
async function halloweenMazeEditPublic(env,g){
  if(!g?.channelId)return false;
  const oldId=String(g.publicMessageId||"");
  // Haunted Maze intentionally follows the same public-board pattern as
  // Color Chaos/Hide & Seek: send the fresh board first, then delete the old one.
  // This avoids Discord/mobile clients keeping a stale board rendered in place.
  let sent=null;
  try{
    sent=await sendChannelMessage(env,g.channelId,halloweenMazeBoardText(g),halloweenMazeRows(g));
  }catch(error){
    console.error("Haunted Maze new board send failed:",error);
    return false;
  }
  if(!sent?.id){
    console.error("Haunted Maze new board send returned no message id.");
    return false;
  }
  const newId=String(sent.id);
  g.publicMessageId=newId;
  if(oldId&&oldId!==newId){
    try{
      const deleted=await discordRequest(env,`/channels/${g.channelId}/messages/${oldId}`,{method:"DELETE"});
      if(!deleted.ok)console.error("Haunted Maze old board delete failed:",deleted.status,await deleted.text());
    }catch(error){
      console.error("Haunted Maze old board delete error:",error);
    }
  }
  return true;
}
async function halloweenMazePublishPublic(env,g){return halloweenMazeEditPublic(env,g);}
function halloweenMazeHowToText(){return ["🗺️ **HAUNTED MAZE — HOW TO PLAY**","","This is a solo maze. Use the **arrow buttons** to move one space at a time.","","⬆️⬅️⬇️➡️ Use the arrows to navigate the maze.","🕯️ Use a Candle to reveal more of the maze.","🧪 Repellent protects you from the ghost for your next **3 moves**.","👻 The ghost moves after every **2 successful moves**, giving you room to plan your escape.","⚡ Every **6th move**, the ghost surges and can move **2 spaces** instead of 1.","🕸️ There are more web traps now; each costs a heart when triggered.","💰 Treasures give bonus Spookies.","","🗝️ Find the Skeleton Key, 💎 Ghost Gem, and 🎃 Cursed Pumpkin.","🚪 Once all three are found, reach the exit to win and unlock the **Phantom Compass**.","","❤️ You have 3 hearts. If they hit 0, the run ends."].join("\n");}
async function halloweenMazeShowMoveModal(env,interaction){return fetch(`https://discord.com/api/v10/interactions/${interaction.id}/${interaction.token}/callback`,{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({type:9,data:{custom_id:"halloween:maze:move_modal",title:"🗺️ Move Through the Haunted Maze",components:[{type:1,components:[{type:4,custom_id:"maze_move",label:"Direction",style:1,placeholder:"Type up, down, left, or right",required:true,max_length:10}]}]}})});}
async function halloweenMazeFinish(env,interaction,state,g,success,reason=""){
  g.status="ended";
  g.finished=true;
  let newlyUnlocked=false;
  if(success){
    const reward=Math.max(250,1000-Math.max(0,g.moves-20)*10);
    await addHalloweenSpookies(env,g.playerId,reward);
    const before=await getPlayer(env,g.playerId);
    newlyUnlocked=!Array.isArray(before.halloweenCollection)||!before.halloweenCollection.includes("phantom_compass");
    await halloweenUnlock(env,g.playerId,"phantom_compass");
    await halloweenMarkPlayed(env,g.playerId,1);
    g.lastEvent=`🏆 **MAZE ESCAPED!** You found all three relics in **${g.moves} moves** and earned **${reward.toLocaleString()} Spookies**! 🧭`;
  }else{
    await halloweenMarkPlayed(env,g.playerId,1);
    g.lastEvent=`💀 **THE MAZE CLAIMED YOU.** ${reason||"Your run is over."}`;
  }
  g.newlyUnlocked=success&&newlyUnlocked;
  await saveGuildState(env,interaction.guild_id,state);
  await halloweenMazeEditPublic(env,g);
  state.halloween.activeGame=null;
  await saveGuildState(env,interaction.guild_id,state);
  return newlyUnlocked;
}
async function halloweenMazeMove(env,interaction,g,state,direction){const user=getUserFromInteraction(interaction);if(!g||g.status!=="playing")return sendText(env,interaction,"🗺️ That Haunted Maze run is no longer active.");if(!user||String(user.id)!==String(g.playerId))return sendText(env,interaction,"❌ This Haunted Maze belongs to another player.");const clean=String(direction||"").trim().toLowerCase();const dirs={up:[-1,0],down:[1,0],left:[0,-1],right:[0,1],u:[-1,0],d:[1,0],l:[0,-1],r:[0,1]};if(!dirs[clean])return sendText(env,interaction,"❌ Type **up**, **down**, **left**, or **right**.");const [dr,dc]=dirs[clean],nr=g.player.r+dr,nc=g.player.c+dc;if(!halloweenMazeWalkable(g,nr,nc))return sendText(env,interaction,"🧱 **Wall!** You can't move that way.");g.player={r:nr,c:nc};g.moves++;halloweenMazeReveal(g,1);const events=[];const relic=g.relics.find(x=>!x.found&&x.r===nr&&x.c===nc);if(relic){relic.found=true;g.collected.push(relic.id);events.push(`${relic.emoji} **${relic.name} FOUND!**`);}const treasure=g.treasures.find(x=>!x.claimed&&x.r===nr&&x.c===nc);if(treasure){treasure.claimed=true;const bonus=randomInt(50,200);await addHalloweenSpookies(env,g.playerId,bonus);events.push(`💰 You found a hidden stash! **+${bonus} Spookies**`);}const trap=g.traps.find(x=>!x.triggered&&x.r===nr&&x.c===nc);if(trap){trap.triggered=true;g.hearts--;events.push("🕸️ **WEB TRAP!** You lost **1 heart**.");}if(g.collected.length===3&&nr===g.exit.r&&nc===g.exit.c){
  const newlyUnlocked=await halloweenMazeFinish(env,interaction,state,g,true);
  return sendText(env,interaction,newlyUnlocked?"🧭 **PHANTOM COMPASS UNLOCKED!** 🎉\n\nYou escaped the Haunted Maze with all three cursed relics. The Phantom Compass has been added to your permanent Halloween collection! 👻": "🗺️ **MAZE ESCAPED!**\n\nYou already own the 🧭 Phantom Compass, so no duplicate collectible was awarded.");
}if(g.hearts<=0){await halloweenMazeFinish(env,interaction,state,g,false,"You ran out of hearts.");return sendText(env,interaction,"💀 **GAME OVER.** The Haunted Maze won this time.");}const repelActive=Number(g.repelMoves||0)>0;const stunned=Number(g.ghostStunMoves||0)>0;const ghostMovesThisTurn=stunned?0:((g.moves%2===0)?((g.moves%6===0)?2:1):0);if(stunned){g.ghostStunMoves=Math.max(0,Number(g.ghostStunMoves||0)-1);events.push("😵‍💫 The ghost is stunned and loses its next chase.");}let ghostCaught=false;for(let step=0;step<ghostMovesThisTurn&&!ghostCaught;step++){const ghostNext=halloweenMazeNextStep(g,g.ghost,g.player);if(repelActive&&ghostNext[0]===g.player.r&&ghostNext[1]===g.player.c){events.push("🧪 The repellent forces the ghost back!");break;}g.ghost={r:ghostNext[0],c:ghostNext[1]};if(g.ghost.r===g.player.r&&g.ghost.c===g.player.c){g.hearts--;ghostCaught=true;events.push("👻 **THE GHOST CAUGHT YOU!** You lost **1 heart**.");g.ghostStunMoves=2;g.player={r:1,c:1};halloweenMazeReveal(g,1);}}if(ghostMovesThisTurn===2&&!ghostCaught)events.push("⚡ **GHOST SURGE!** The ghost moved twice this turn.");if(repelActive)g.repelMoves=Math.max(0,g.repelMoves-1);if(g.hearts<=0){await halloweenMazeFinish(env,interaction,state,g,false,"The ghost took your last heart.");return sendText(env,interaction,"💀 **GAME OVER.** The ghost caught you one time too many.");}if(g.collected.length===3)events.push("🗝️ **All three relics are yours. Find 🚪 to escape!**");g.lastEvent=events.length?events.join("\n"):"👣 You move deeper into the maze...";await saveGuildState(env,interaction.guild_id,state);await halloweenMazeEditPublic(env,g);return sendText(env,interaction,"👣 **Move recorded.** The maze shifts around you...");}
async function halloweenMazeComponent(env,interaction,parts){const state=await getGuildState(env,interaction.guild_id),g=state.halloween?.activeGame,user=getUserFromInteraction(interaction);if(!g||g.type!=="maze")return sendText(env,interaction,"🗺️ There is no active Haunted Maze.");if(!user||String(user.id)!==String(g.playerId))return sendText(env,interaction,"❌ This Haunted Maze belongs to another player.");const action=parts[2];if(action==="move"){const direction=parts[4]||"";return halloweenMazeMove(env,interaction,g,state,direction);}if(action==="howto")return sendText(env,interaction,halloweenMazeHowToText(),[row(button("⬅️ Back to Maze",`halloween:maze:back:${g.id}`,2))]);if(action==="back")return sendText(env,interaction,halloweenMazeBoardText(g),halloweenMazeRows(g));if(action==="light"){if(g.status!=="playing")return sendText(env,interaction,"🗺️ This maze run has ended.");if(g.candles<=0)return sendText(env,interaction,"🕯️ You're out of candles!");g.candles--;halloweenMazeReveal(g,3);g.lastEvent="🕯️ Your candle burns brightly. The maze reveals itself...";await saveGuildState(env,interaction.guild_id,state);await halloweenMazeEditPublic(env,g);return sendText(env,interaction,"🕯️ **The darkness recedes.**");}if(action==="repellent"){if(g.status!=="playing")return sendText(env,interaction,"🗺️ This maze run has ended.");if(g.repellents<=0)return sendText(env,interaction,"🧪 You're out of ghost repellent!");g.repellents--;g.repelMoves=3;g.lastEvent="🧪 **GHOST REPELLENT ACTIVE!** The ghost cannot hurt you for the next 3 moves.";await saveGuildState(env,interaction.guild_id,state);await halloweenMazeEditPublic(env,g);return sendText(env,interaction,"🧪 **Repellent activated!**");}if(action==="end"){g.status="ended";g.finished=true;g.lastEvent="🏃 **RUN ENDED.** You escaped the maze... but left the relics behind.";await halloweenMazeEditPublic(env,g);state.halloween.activeGame=null;await saveGuildState(env,interaction.guild_id,state);return sendText(env,interaction,"🏃 **Haunted Maze ended.** No collectible was awarded.");}return sendText(env,interaction,"❌ Unknown Haunted Maze action.");}

