  const user=getUserFromInteraction(interaction);
  const g={id:`zp-${Date.now().toString(36)}-${randomInt(100,999)}`,type:"zombie",status:"lobby",guildId:interaction.guild_id,channelId:interaction.channel_id,publicMessageId:"",hostId:user.id,players:{[user.id]:{id:user.id,name:user.global_name||user.username||"Werewife"}}};
  state.halloween={activeGame:g};
  await saveGuildState(env,interaction.guild_id,state);
