/* =========================================================
   REGISTER COMMANDS
========================================================= */

async function registerCommands(
  env
) {
  const response =
    await discordRequest(
      env,
      `/applications/${env.CLIENT_ID}/commands`,
      {
        method: "PUT",
        body: JSON.stringify(
          COMMANDS
        )
      }
    );

  return response;
}

/* =========================================================
   DISCORD SIGNATURE VERIFICATION
========================================================= */

function hexToUint8Array(
  hex
) {
  const bytes =
    new Uint8Array(
      hex.length / 2
    );

  for (
    let i = 0;
    i < bytes.length;
    i++
  ) {
    bytes[i] =
      parseInt(
        hex.substr(
          i * 2,
          2
        ),
        16
      );
  }

  return bytes;
}

async function verifySignature(
  request,
  env
) {
  const signature =
    request.headers.get(
      "X-Signature-Ed25519"
    );

  const timestamp =
    request.headers.get(
      "X-Signature-Timestamp"
    );

  if (
    !signature ||
    !timestamp ||
    !env.PUBLIC_KEY
  ) {
    return false;
  }

  const body =
    await request
      .clone()
      .text();

  const message =
    new TextEncoder().encode(
      timestamp + body
    );

  const signatureBytes =
    hexToUint8Array(
      signature
    );

  const publicKeyBytes =
    hexToUint8Array(
      env.PUBLIC_KEY
    );

  try {
    const publicKey =
      await crypto.subtle.importKey(
        "raw",
        publicKeyBytes,
        {
          name: "Ed25519"
        },
        false,
        ["verify"]
      );

    return await crypto.subtle.verify(
      {
        name: "Ed25519"
      },
      publicKey,
      signatureBytes,
      message
    );
  } catch {
    return false;
  }
}

/* =========================================================
   MAIN WORKER
========================================================= */

async function processPastelTimers(env){
  const guildIds=await getKnownGuildIds(env);
  const now=Date.now();
  for(const guildId of guildIds){
    try{
      const games=await listPastelGames(env,guildId);
      for(let game of games){
        if(!game||game.status!=="playing")continue;
      if(!Number(game.turnStartedAt)){game.turnStartedAt=now;await pastelSave(env,game);continue;}
      if(now-Number(game.turnStartedAt)<=2*60*1000)continue;
      const snapshotTurnId=game.turnId;
      const snapshotTurnStartedAt=Number(game.turnStartedAt);
      /* A scheduled timer can overlap a player's button click. Re-read KV immediately
         before applying an AFK loss so an older timer can never overwrite a newer move. */
      const latestGame=await getPastelGame(env,guildId,game.id);
      if(!latestGame||latestGame.id!==game.id||latestGame.status!=="playing")continue;
      if(latestGame.turnId!==snapshotTurnId||Number(latestGame.turnStartedAt)!==snapshotTurnStartedAt)continue;
      const current=pastelFindOwned(latestGame,latestGame.turnId);
      if(!current?.alive)continue;
      game=latestGame;
      current.alive=false;
      current.lossRecorded=true;
      current.afkForfeited=true;
      for(const row of game.board||[])for(const cell of row){if(cell.owner===current.id){cell.owner="blackout";cell.color=0;cell.heart=false;cell.wild=false;cell.start=false;}}
      const player=await getPlayer(env,current.id);
      current.resultBeforeRating=Number(player.pastelRating||0);
      current.resultBeforeLevel=pastelRatingLevel(player.pastelRating);
      player.pastelLosses=Number(player.pastelLosses||0)+1;
      player.pastelRating=Math.max(0,Number(player.pastelRating||0)-50);
      player.pastelLevel=pastelRatingLevel(player.pastelRating);
      await savePlayer(env,player,current.id);
      const alive=Object.values(game.players||{}).filter(p=>p.alive);
      if(alive.length<=1){
        const winner=alive[0];
        if(winner){
          const results=await pastelFinish(env,game,winner.id,`⏰ <@${current.id}> was AFK for more than 2 minutes and forfeited.`);
          await pastelPublishEndMessage(env,game,`⏰ **AFK TIMEOUT!** <@${current.id}> was inactive for more than **2 minutes** and forfeited.\n\n🏆 <@${winner.id}> wins Color Chaos!\n✨ **+${PASTEL_WIN_XP} EXP earned!**\n\n${pastelResultsText(results,winner.id)}`).catch(()=>null);
        }
        continue;
      }
      game.turnId=alive[0].id;
      game.turnStartedAt=now;
      game.lastMove=`⏰ **<@${current.id}> timed out!** They were AFK for more than 2 minutes and forfeited. Their territory is blacked out.`;
      const legalPlayersAfterAFK=pastelPlayersWithLegalMoves(game);
      if(legalPlayersAfterAFK.length===0){
        await pastelFinishNoMoves(env,game,"🏁 No legal moves remained after an AFK forfeit.");
        continue;
      }
      if(legalPlayersAfterAFK.length===1){
        const winner=pastelWinner(game);
        if(winner){
          const results=await pastelFinish(env,game,winner.id,"🏁 Only one active player had a legal move remaining after an AFK forfeit.");
          await pastelPublishEndMessage(env,game,`${game.lastMove}\n\n🏁 **COLOR CHAOS OVER!** <@${winner.id}> wins — no other active player had a legal move remaining!\n✨ **+${PASTEL_WIN_XP} EXP earned!**\n\n${pastelResultsText(results,winner.id)}`);
        }
        continue;
      }
      await pastelSave(env,game);
      await sendPastelBoard(env,{token:game.interactionToken},game).catch(error=>console.error("Pastel AFK board update failed:",error));
      await sendPastelTurnMessage(env,game,game.turnId).catch(error=>console.error("Pastel AFK turn ping failed:",error));
      }
    }catch(error){console.error(`Pastel timer failed for guild ${guildId}:`,error);}
  }
}

async function processCourtTrashRelease(env){
    const now=Date.now(); const keys=await listAllPlayerKeys(env);
    for(const userId of keys){
      try{
        const player=await getPlayer(env,userId); const until=Number(player.courtTrashReleaseUntil||0);
        if(until<=0)continue;
        if(until<=now){player.courtTrashReleaseUntil=0;player.courtTrashReleaseNextAt=0;player.courtTrashReleaseChannelId="";await savePlayer(env,player,userId);continue;}
        if(Number(player.courtTrashReleaseNextAt||0)>now)continue;
        const requested=randomInt(100,2000),balance=Math.max(0,Number(player.sparkles||0)),actual=Math.min(requested,balance);
        player.sparkles=Math.max(0,balance-actual); player.courtTrashReleaseNextAt=now+30*60000; await savePlayer(env,player,userId);
        const messages=["The trash can is hungry again.","Payment accepted. Freedom denied.","The raccoons found your Sparkles. This is unfortunate for you.","Raccoon Finance has processed another completely unnecessary fee.","The trash can has reviewed your finances and would like another payment.","Your Sparkles have been legally converted into trash-can property.","The raccoons have returned for their regularly scheduled nonsense fee.","Judge Pickles says you still owe the trash can."];
        const channelId=String(player.courtTrashReleaseChannelId||"");
        if(channelId)await sendChannelMessage(env,channelId,`🗑️🦝 **TRASH CAN RELEASE FEE**\n\n<@${player.userId}> ${messages[randomInt(0,messages.length-1)]}\n\n💰 **${actual.toLocaleString()} Sparkles confiscated.**${actual<requested?`\n\n😭 They only had **${actual.toLocaleString()}**, so the raccoons took all of it.`:""}`);
      }catch(error){console.error(`Trash Release processing failed for ${userId}:`,error);}
    }
  }


 /* =========================================================
   RACCOON RUMBLE TIMER
========================================================= */

async function processRumbleTimers(env) {
  const rawGuilds = await env.TREE_DATA.list({ prefix: "guild:" });
  for (const key of rawGuilds.keys || []) {
    const guildId = String(key.name || "").slice(6);
    if (!guildId) continue;
    try {
      const state = await getGuildState(env, guildId);
      const game = state.rumble;
      if (!game || game.status !== "playing" || !Number(game.phaseEndsAt || 0) || Date.now() < Number(game.phaseEndsAt)) continue;
      // Missing choices become Lay Low. This makes abandoned phones harmless
      // and prevents a Rumble from hanging forever.
      for (const p of rumblePlayers(game)) {
        if (!p.submitted) {
          p.submitted = true;
          p.action = "laylow";
          p.targetId = null;
          p.lateAutoChoice = true;
        }
      }
      await saveGuildState(env, guildId, state);
      await rumbleResolveRound(env, game);
    } catch (error) {
      console.error(`Raccoon Rumble timer failed for guild ${guildId}:`, error);
    }
  }
}



 /* =========================================================
   RACCOON SUIT — 24-HOUR HOURLY PAYDAYS
========================================================= */

const RACCOON_SUIT_DURATION = 24 * 60 * 60 * 1000;
const RACCOON_SUIT_HOUR = 60 * 60 * 1000;

function raccoonSuitPayout() {
  const roll = randomInt(1, 100);
  if (roll <= 20) return 15000;
  if (roll <= 40) return 20000;
  if (roll <= 60) return 25000;
  if (roll <= 75) return 35000;
  if (roll <= 87) return 50000;
  if (roll <= 95) return 75000;
  if (roll <= 99) return 150000;
  return 300000;
}

async function processRaccoonSuitPaydays(env) {
  const now = Date.now();
  const playerKeys = await listAllPlayerKeys(env);

  for (const userId of playerKeys) {
    try {
      const player = await getPlayer(env, userId);
      const startedAt = Number(player.raccoonSuitStartedAt || 0);
      if (!startedAt) continue;

      const endAt = startedAt + RACCOON_SUIT_DURATION;
      let nextAt = Number(player.raccoonSuitNextPayoutAt || 0);
      let payoutsMade = Number(player.raccoonSuitPayoutsMade || 0);
      let totalEarned = Number(player.raccoonSuitTotalEarned || 0);
      if (!nextAt) nextAt = startedAt + RACCOON_SUIT_HOUR;

      const payouts = [];
      while (payoutsMade < 24 && nextAt <= now && nextAt <= endAt) {
        const amount = raccoonSuitPayout();
        player.sparkles = Number(player.sparkles || 0) + amount;
        payoutsMade += 1;
        totalEarned += amount;
        payouts.push(amount);
        nextAt += RACCOON_SUIT_HOUR;
      }

      if (payouts.length) {
        player.raccoonSuitPayoutsMade = payoutsMade;
        player.raccoonSuitTotalEarned = totalEarned;
        player.raccoonSuitNextPayoutAt = nextAt;
        player.badgeStats = player.badgeStats && typeof player.badgeStats === "object" ? player.badgeStats : {};
        player.badgeStats.sparklesEarned = Number(player.badgeStats.sparklesEarned || 0) + payouts.reduce((a,b) => a + b, 0);
        await savePlayer(env, player, userId, { skipSparkleMagnet: true });

        if (payouts.length === 1) {
          const amount = payouts[0];
          const jackpot = amount >= 150000 ? "\n\n🎰 **JACKPOT PAYDAY!**" : "";
          await sendUserDM(env, userId, `🦝💼 **RACCOON SUIT PAYDAY!**\n\n💰 You received **${amount.toLocaleString()} ✨**.${jackpot}\n\n📊 **Suit earnings:** ${totalEarned.toLocaleString()} ✨\n⏰ **Paydays:** ${payoutsMade}/24`);
        } else {
          const batchTotal = payouts.reduce((a,b) => a + b, 0);
          await sendUserDM(env, userId, `🦝💼 **RACCOON SUIT PAYDAY CATCH-UP!**\n\nThe scheduled worker was late, so you received **${payouts.length} missed paydays** totaling **${batchTotal.toLocaleString()} ✨**.\n\n📊 **Suit earnings:** ${totalEarned.toLocaleString()} ✨\n⏰ **Paydays:** ${payoutsMade}/24`);
        }
      }

      if (payoutsMade >= 24 || now >= endAt) {
        const finalTotal = Number(player.raccoonSuitTotalEarned || totalEarned);
        player.raccoonSuitStartedAt = 0;
        player.raccoonSuitNextPayoutAt = 0;
        player.raccoonSuitPayoutsMade = 0;
        player.raccoonSuitTotalEarned = 0;
        await savePlayer(env, player, userId, { skipRaccoonEmpireBonus: true, skipSparkleMagnet: true });
        await sendUserDM(env, userId, `🦝🎓 **RACCOON SUIT CONTRACT EXPIRED!**\n\nYour 24-hour payday event is over.\n\n💰 **Base suit earnings:** ${finalTotal.toLocaleString()} ✨\n⏰ **Paydays completed:** ${payoutsMade}/24\n\nThe raccoon corporation thanks you for your service. 🦝💼`);
      }
    } catch (error) {
      console.error(`Raccoon Suit payday failed for ${userId}:`, error);
    }
  }
}

/* =========================================================
   RACCOON EMPIRE — WEEKLY DIVIDENDS
========================================================= */

const RACCOON_EMPIRE_WEEK = 7 * 24 * 60 * 60 * 1000;
const RACCOON_EMPIRE_WEEKLY_PAYOUT = 20000;

async function processRaccoonEmpireDividends(env) {
  const now = Date.now();
  const playerKeys = await listAllPlayerKeys(env);

  for (const userId of playerKeys) {
    try {
      const player = await getPlayer(env, userId);

      if (raccoonMartCount(player, "raccoon_empire") < 1) continue;

      let lastDividend = Number(player.raccoonEmpireLastDividendAt || 0);

      // Safety migration: if an Empire holder somehow has no timestamp,
      // start their first 7-day clock now rather than granting a surprise payout.
      if (!lastDividend) {
        player.raccoonEmpireLastDividendAt = now;
        await savePlayer(env, player, userId, {
          skipRaccoonEmpireBonus: true,
          skipSparkleMagnet: true
        });
        continue;
      }

      if (now - lastDividend < RACCOON_EMPIRE_WEEK) continue;

      // Catch up missed weekly dividends without paying multiple weeks during
      // one cron pass. Each successful pass advances exactly one 7-day period.
      player.sparkles = Number(player.sparkles || 0) + RACCOON_EMPIRE_WEEKLY_PAYOUT;
      player.badgeStats = player.badgeStats && typeof player.badgeStats === "object"
        ? player.badgeStats
        : {};
      player.badgeStats.sparklesEarned =
        Number(player.badgeStats.sparklesEarned || 0) + RACCOON_EMPIRE_WEEKLY_PAYOUT;

      player.raccoonEmpireLastDividendAt = lastDividend + RACCOON_EMPIRE_WEEK;

      await savePlayer(env, player, userId, {
        skipRaccoonEmpireBonus: true,
        skipSparkleMagnet: true
      });

      // If the worker was down for multiple weeks, the next scheduled pass
      // will pay the next missed week. This avoids a huge accidental lump sum.
    } catch (error) {
      console.error(`Raccoon Empire dividend failed for ${userId}:`, error);
    }
  }
}


async function handleBombExpirationRequest(env, ctx, guildId, bombId) {
  if (!guildId || !bombId) return;

  // Keep this execution comfortably below Cloudflare's request lifetime.
  await new Promise(resolve => setTimeout(resolve, 20 * 1000));

  try {
    const state = await getGuildState(env, guildId);
    state.bombs = state.bombs && typeof state.bombs === "object" ? state.bombs : {};
    const bomb = state.bombs[bombId];

    // The live-state check inside applyBombDetonation() is the final guard
    // against defused/wrong-wire/already-detonated bombs.
    if (
      bomb &&
      bomb.status === "pending" &&
      Number(bomb.expiresAt || 0) <= Date.now()
    ) {
      await applyBombDetonation(env, bomb, "expired");
    }
  } catch (error) {
    console.error("Bomb second-stage expiration failed:", error);
  }
}

export default {
  async fetch(
    request,
    env,
    ctx
  ) {
    const url =
      new URL(
        request.url
      );

    if (
      request.method === "GET" &&
      url.pathname === "/__werewives_bomb_expire"
    ) {
      const guildId = url.searchParams.get("guild");
      const bombId = url.searchParams.get("bomb");

      // A timer request is only allowed to detonate a bomb whose persisted
      // expiresAt has actually passed. It cannot force an early explosion.
      ctx.waitUntil(
        handleBombExpirationRequest(env, ctx, guildId, bombId)
      );

      return new Response("Bomb expiration timer armed.", { status: 202 });
    }

    if (
      request.method ===
        "GET" &&
      url.pathname === "/"
    ) {
      return new Response(
        "Werewives Tree Bot is alive! 🌳💖",
        {
          status: 200
        }
      );
    }

    if (
      request.method ===
        "GET" &&
      url.pathname ===
        "/register"
    ) {
      const response =
        await registerCommands(
          env
        );

      const text =
        await response.text();

      return new Response(
        text,
        {
          status:
            response.status,
          headers: {
            "Content-Type":
              "application/json"
          }
        }
      );
    }

    if (
      request.method !==
        "POST" ||
      url.pathname !==
        "/interactions"
    ) {
      return new Response(
        "Not found",
        {
          status: 404
        }
      );
    }

    const valid =
      await verifySignature(
        request,
        env
      );

    if (!valid) {
      return new Response(
        "Invalid request signature",
        {
          status: 401
        }
      );
    }

    let interaction;

    try {
      interaction =
        await request.json();
    } catch {
      return new Response(
        "Invalid JSON",
        {
          status: 400
        }
      );
    }

    /*
      Discord PING
    */

    if (
      interaction.type === 1
    ) {
      return new Response(
        JSON.stringify({
          type: 1
        }),
        {
          headers: {
            "Content-Type":
              "application/json"
          }
        }
      );
    }

    // BADGE FAST PATH: handle badge components before the normal interaction
    // router. This path does not touch KV, waitUntil, defer logic, or any
    // other middleware before returning Discord's response.
    if (interaction.type === 3) {
      const fastBadgeId = String(interaction.data?.custom_id || "");
      if (fastBadgeId.startsWith("profile_badge_guide:")) {
        try {
          const parts = fastBadgeId.split(":");
          const targetId = parts[1] || "";
          const page = Number(parts[2] || 0);
          const unlockedMask = parts[3] || "0";
          const equippedMask = parts[4] || "0";
          const userId = String(interaction.member?.user?.id || interaction.user?.id || "");
          if (!userId || userId !== targetId) {
            return new Response(JSON.stringify({type:4,data:{content:"❌ You can only view your own badge guide.",flags:64}}),{status:200,headers:{"Content-Type":"application/json"}});
          }
          const guide = profileBadgeGuideFromPage(userId,page,unlockedMask,equippedMask);
          return new Response(JSON.stringify({type:4,data:guide}),{status:200,headers:{"Content-Type":"application/json"}});
        } catch (error) {
          console.error("Badge guide fast-path error:",error);
          return new Response(JSON.stringify({type:4,data:{content:`❌ Couldn't open the badge guide: ${error?.message||"Unknown error"}`,flags:64}}),{status:200,headers:{"Content-Type":"application/json"}});
        }
      }
      if (fastBadgeId.startsWith("profile_badges:")) {
        try {
          const parts = fastBadgeId.split(":");
          const targetId = parts[1] || "";
          const page = Number(parts[2] || 0);
          const unlockedMask = parts[3] || "0";
          const equippedMask = parts[4] || "0";
          const userId = String(interaction.member?.user?.id || interaction.user?.id || "");
          if (!userId || userId !== targetId) {
            return new Response(JSON.stringify({
              type: 4,
              data: { content: "❌ You can only manage badges on your own profile.", flags: 64 }
            }), { status: 200, headers: { "Content-Type": "application/json" } });
          }
          const menu = profileBadgeMenuFromMasks(userId, page, unlockedMask, equippedMask);
          return new Response(JSON.stringify({
            type: 4,
            data: { content: menu.content, components: menu.components, flags: 64 }
          }), { status: 200, headers: { "Content-Type": "application/json" } });
        } catch (error) {
          console.error("Badge fast-path error:", error);
          return new Response(JSON.stringify({
            type: 4,
            data: { content: `❌ Couldn't open your badges: ${error?.message || "Unknown error"}`, flags: 64 }
          }), { status: 200, headers: { "Content-Type": "application/json" } });
        }
      }
    }

    /*
      IMPORTANT: Discord only gives us about 3 seconds to acknowledge an
      interaction. Do NOT make a KV/Discord API call before returning the
      acknowledgement. We return the acknowledgement directly from this
      Worker request, then continue the game work in waitUntil().

      This is especially important for Heist and Chaos Island because their
      handlers do several KV reads/writes and Discord message updates.
    */
    const isHelpCommand = interaction.type === 2 && interaction.data?.name === "help";
    if (isHelpCommand) {
      return new Response(JSON.stringify({
        type: 4,
        data: { content: helpText() }
      }), {
        status: 200,
        headers: { "Content-Type": "application/json" }
      });
    }

    const isNewsCommand = interaction.type === 2 && interaction.data?.name === "news";
    const isBlacklistCommand = interaction.type === 2 && (interaction.data?.name === "blacklist" || interaction.data?.name === "unblacklist" || interaction.data?.name === "blacklist-list");

    const isExperimentCommand =
      interaction.type === 2 && interaction.data?.name === "experiment";
    const isHeistCommand =
      interaction.type === 2 && interaction.data?.name === "heist";
    const isIslandCommand =
      interaction.type === 2 && interaction.data?.name === "island";
    const isBattleCommand =
      interaction.type === 2 && (interaction.data?.name === "battle" || interaction.data?.name === "battleshop" || interaction.data?.name === "battle-end");
    const isSoloCommand =
      interaction.type === 2 && interaction.data?.name === "solo";
    const isCrimeCommand =
      interaction.type === 2 && interaction.data?.name === "sparklecrime";
    const isPastelCommand =
      interaction.type === 2 && interaction.data?.name === "colorchaos";
    const isColorCommand =
      interaction.type === 2 && interaction.data?.name === "color";
    const isFreeCommand =
      interaction.type === 2 && interaction.data?.name === "free";
    const isBlameCommand =
      interaction.type === 2 && interaction.data?.name === "blame";
    const isProfileCommand =
      interaction.type === 2 && interaction.data?.name === "profile";
    // /tree performs KV work and Browser Rendering, so it must be acknowledged
    // immediately just like the other long-running commands.
    const isTreeCommand =
      interaction.type === 2 && interaction.data?.name === "tree";
    const isTitlesCommand =
      interaction.type === 2 && interaction.data?.name === "titles";
    const isBirthdayCommand = interaction.type === 2 && interaction.data?.name === "birthday";
    const isPunishmentCommand =
      interaction.type === 2 && (interaction.data?.name === "pickle" || interaction.data?.name === "timeout");
    const isCourtCommand =
      interaction.type === 2 && (interaction.data?.name === "court" || interaction.data?.name === "court-leaderboard");
    const customId = String(interaction.data?.custom_id || "");
    const isSparkleShopCommand = interaction.type === 2 && interaction.data?.name === "sparkleshop";
    const isBombCommand = interaction.type === 2 && interaction.data?.name === "bomb";
    const isSparkleShopComponent = interaction.type === 3 && (customId.startsWith("sparkleshop:") || customId.startsWith("sparklepurchase:"));
    const isBombComponent = interaction.type === 3 && customId.startsWith("bomb:");
    const isNewsComponent = interaction.type === 3 && customId.startsWith("news:ok:");
    const isRumbleCommand = interaction.type === 2 && interaction.data?.name === "rumble";
    const isCoupCommand = interaction.type === 2 && interaction.data?.name === "coup";
    const isCoupComponent = interaction.type === 3 && customId.startsWith("coup:");
    const isCrimeComponent = interaction.type === 3 && customId.startsWith("crime:");
    const isExperimentComponent = interaction.type === 3 && customId.startsWith("experiment:");
    const isRumbleComponent = interaction.type === 3 && customId.startsWith("rumble:");

    const isHeistComponent = interaction.type === 3 && customId.startsWith("heist:");
    const isIslandComponent = interaction.type === 3 && customId.startsWith("island:");
    const isBattleComponent = interaction.type === 3 && (customId.startsWith("battle:") || customId.startsWith("battleitem:") || customId.startsWith("bshop:"));
    const isPastelComponent = interaction.type === 3 && customId.startsWith("pastel:");
    const isSurpriseAlertComponent = interaction.type === 3 && customId.startsWith("surprise_alert:");
    const isTitlesComponent = interaction.type === 3 && (customId.startsWith("title:") || customId.startsWith("nameeffect:"));
    const isBirthdayComponent = interaction.type === 3 && customId.startsWith("birthday:");
    const isHalloweenComponent = interaction.type === 3 && (customId.startsWith("halloween:") || customId.startsWith("collection:"));
    const isSpookSmashComponent = interaction.type === 3 && (customId === "halloween:start:spook" || customId.startsWith("halloween:spook:"));
    const isPermanentGameComponent = interaction.type === 3 && (customId.startsWith("talent:") || customId.startsWith("truthpass:"));
    const isBirthdayModal = interaction.type === 5 && customId === "birthday:cursemodal";
    const isPermanentGameModal = interaction.type === 5 && (customId === "talent:modal" || customId === "truthpass:modal");
    // Tree buttons can involve KV reads and optional Browser Rendering.
    // Acknowledge them immediately so Discord never leaves the button
    // spinning on "Bot is thinking..." while the tree action finishes.
    const isTreeComponent = interaction.type === 3 && customId.startsWith("tree:");
    // Shop buttons can involve KV reads/writes before the response is ready.
    // Acknowledge them immediately so Discord never hits the 3-second timeout.
    const isRaccoonMartComponent =
      interaction.type === 3 && customId.startsWith("raccoonmart:");

    const isShopComponent =
      interaction.type === 3 &&
      (
        customId === "shop" ||
        customId === "shop_backgrounds" ||
        customId === "shop_trees" ||
        customId === "shop_decorations" ||
        customId === "shop_effects" ||
        customId === "shop_animated_effects" ||
        customId.startsWith("shop_animated_effects:") ||
        customId === "shop_limited" ||
        customId === "shop_limited_halloween" ||
        customId === "shop_special" ||
        customId === "back_tree" ||
        customId === "customize" ||
        customId === "inventory" ||
        customId.startsWith("buy_") ||
        customId.startsWith("limited_set:") ||
        customId.startsWith("inventory:")
      );

    const isBadgeComponent =
      interaction.type === 3 &&
      (
        customId.startsWith("profile_badges:") ||
        customId.startsWith("equip_badge:") ||
        customId === "unequip_badges"
      );

    // Badge interactions are PRIVATE and may perform KV reads/writes.
    // Let the generic interaction path send the ephemeral type-5 ACK immediately,
    // then let the handler build/edit the private badge menu. Do NOT build the
    // badge payload before the initial ACK, because getPlayer/savePlayer can
    // exceed Discord's 3-second interaction window.

    const isCustomizeComponent =
      interaction.type === 3 &&
      (
        customId === "customize" ||
        customId.startsWith("profile_frames:") ||
        customId.startsWith("profile_back:") ||
        customId.startsWith("equip_frame_") ||
        customId === "custom_effects" ||
        customId.startsWith("custom_effects_page_") ||
        customId.startsWith("equip_")
      );

    // SPOOK N SMASH FAST PATH: acknowledge with type 6 so the button never
    // sits in Discord's loading/thinking state while Browser Rendering runs.
    if (interaction.type === 3 && isSpookSmashComponent) {
      const ack = await fetch(
        `https://discord.com/api/v10/interactions/${interaction.id}/${interaction.token}/callback`,
        {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ type: 6 })
        }
      );
      if (!ack.ok) {
        console.error("Spook N Smash initial response failed:", ack.status, await ack.text());
        return new Response("OK", { status: 200 });
      }
      interaction.__deferred = true;
      interaction.__deferredUpdate = true;
      interaction.__deferredEphemeral = false;
      interaction.__requestUrl = request.url;
      ctx.waitUntil((async () => {
        try {
          await handleComponent(env, interaction, ctx);
        } catch (error) {
          console.error("Spook N Smash component error:", error);
          try {
            await editOriginalResponse(env, interaction, {
              content: `❌ Spook N Smash error: ${error?.message || "Unknown error"}`,
              components: []
            });
          } catch (editError) {
            console.error("Could not send Spook N Smash error:", editError);
          }
        }
      })());
      return new Response("OK", { status: 200 });
    }

    // HALLOWEEN FAST PATH: acknowledge Halloween buttons immediately and
    // bypass the global pre-handler checks. Those checks can perform several
    // KV reads before the Halloween handler runs, which can make Discord
    // buttons appear stuck. The handler edits this initial response afterward.
    if (interaction.type === 3 && isHalloweenComponent) {
      const spookNsmashPublic =
        customId === "halloween:start:spook" ||
        customId.startsWith("halloween:spook:");
      const privateHalloween =
        customId === "collection:halloween:open" ||
        customId.startsWith("collection:halloween:page:") ||
        customId === "collection:halloween:unlock" ||
        customId === "halloween:hide:action" ||
        customId === "halloween:hide:howto" ||
        customId.startsWith("halloween:hide:hunter:") ||
        customId.startsWith("halloween:hide:investigate:") ||
        customId.startsWith("halloween:hide:listen:") ||
        customId.startsWith("halloween:hide:track:") ||
        customId.startsWith("halloween:hide:trap:") ||
        customId.startsWith("halloween:hide:captureroom:") ||
        customId.startsWith("halloween:hide:capturetarget:") ||
        customId.startsWith("halloween:hide:move:") ||
        customId.startsWith("halloween:hide:stay:") ||
        customId === "halloween:hide:ability" ||
        customId === "halloween:hide:ghost" ||
        customId.startsWith("halloween:zombie:") ||
        customId.startsWith("halloween:trivia:");

      const ack = await fetch(
        `https://discord.com/api/v10/interactions/${interaction.id}/${interaction.token}/callback`,
        {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify(
            spookNsmashPublic
              ? { type: 6 }
              : {
                  type: 5,
                  data: {
                    ...(privateHalloween ? { flags: 64 } : {})
                  }
                }
          )
        }
      );
      if (!ack.ok) {
        console.error("Halloween initial response failed:", ack.status, await ack.text());
        return new Response("OK", { status: 200 });
      }

      interaction.__deferred = true;
      interaction.__deferredUpdate = spookNsmashPublic;
      interaction.__deferredEphemeral = privateHalloween;
      interaction.__requestUrl = request.url;

      ctx.waitUntil((async () => {
        try {
          await handleComponent(env, interaction, ctx);
        } catch (error) {
          console.error("Halloween component error:", error);
          try {
            await editOriginalResponse(env, interaction, {
              content: `❌ Halloween button error: ${error?.message || "Unknown error"}`,
              components: []
            });
          } catch (editError) {
            console.error("Could not send Halloween component error:", editError);
          }
        }
      })());

      return new Response("OK", { status: 200 });
    }

    const relevant = interaction.type === 2 || interaction.type === 3 || interaction.type === 5;

    // Bomb buttons are public and can perform several KV operations.
    // Use the same immediate type-6 public ACK as the other long-running
    // component handlers. The Bomb handler then edits @original after its KV
    // work completes. This is important because charging Sparkles, creating
    // the bomb record, and building the target menu can take longer than
    // Discord's 3-second initial interaction window.

    // Color Key is a private, player-only response. It never edits the public game board.
    if (isPastelComponent && /^pastel:colorkey:[^:]+$/.test(customId)) {
      try {
        const gameId=customId.split(":")[2];
        const state=await getGuildState(env,interaction.guild_id);
        const game=await getPastelGame(env,interaction.guild_id,gameId);
        const user=getUserFromInteraction(interaction);
        if (!game || game.id!==gameId || game.status!=="playing") {
          return new Response(JSON.stringify({type:4,data:{content:"❌ That Color Chaos game is no longer active.",flags:64}}),{status:200,headers:{"Content-Type":"application/json"}});
        }
        if (!user || !game.players?.[user.id] || game.players[user.id].alive===false) {
          return new Response(JSON.stringify({type:4,data:{content:"❌ Only an active Color Chaos player can view the Color Key.",flags:64}}),{status:200,headers:{"Content-Type":"application/json"}});
        }
        return new Response(JSON.stringify({type:4,data:{content:pastelColorKeyText(game),flags:64}}),{status:200,headers:{"Content-Type":"application/json"}});
      } catch(error) {
        console.error("Color Key response error:",error);
        return new Response(JSON.stringify({type:4,data:{content:`❌ Couldn't load the Color Key: ${error?.message||"Unknown error"}`,flags:64}}),{status:200,headers:{"Content-Type":"application/json"}});
      }
    }

    // Titles must return the actual menu in the initial Discord response.
    // Waiting on waitUntil() after sending a placeholder can leave some Discord
    // clients stuck on the loading message forever. Build the small menu here.
    if (isTitlesCommand) {
      try {
        const data = await buildTitlesResponseData(env, interaction);
        return new Response(JSON.stringify({ type: 4, data }), {
          status: 200,
          headers: { "Content-Type": "application/json" }
        });
      } catch (error) {
        console.error("Titles initial response error:", error);
        return new Response(JSON.stringify({
          type: 4,
          data: { content: `❌ Couldn't load Titles & Name Effects: ${error?.message || "Unknown error"}`, flags: 64 }
        }), {
          status: 200,
          headers: { "Content-Type": "application/json" }
        });
      }
    }

    // Birthday Shop buttons use an immediate type-4 response instead of a
    // type-6 update ACK. This gives Discord a complete initial interaction
    // response immediately, then the real shop is edited into that response
    // after the KV reads finish. This avoids both the 3-second timeout and the
    // blank/no-op behavior caused by the previous type-6 path.
    if (interaction.type === 3 && /^birthday:shop(?::\d+)?$/.test(customId)) {
      const ack = await fetch(
        `https://discord.com/api/v10/interactions/${interaction.id}/${interaction.token}/callback`,
        {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({
            type: 4,
            data: { content: "🦇🛍️ Loading the Midnight Birthday Shop..." }
          })
        }
      );
      if (!ack.ok) {
        console.error("Birthday Shop initial response failed:", ack.status, await ack.text());
        return new Response("OK", { status: 200 });
      }
      // The type-4 response above creates @original, which can safely be
      // edited by sendText/editOriginalResponse after the KV work completes.
      interaction.__deferred = true;
      interaction.__deferredUpdate = false;
      interaction.__deferredEphemeral = true;
      const page = Number(customId.split(":")[2] || 0);
      ctx.waitUntil((async () => {
        try {
          await showBirthdayShop(env, interaction, page);
        } catch (error) {
          console.error("Birthday Shop button error:", error);
          try {
            await editOriginalResponse(env, interaction, {
              content: `❌ Couldn't open the Birthday Shop: ${error?.message || "Unknown error"}`,
              components: []
            });
          } catch (editError) {
            console.error("Could not send Birthday Shop error:", editError);
          }
        }
      })());
      return new Response("OK", { status: 200 });
    }

    // Birthday Curse's Enter Answer button must open a Discord modal (type 9)
    // directly. Do NOT send the normal deferred type-5 acknowledgement first,
    // because Discord only allows the modal callback as the initial response.
    // Deferring first can make the button appear to do nothing until it is
    // clicked repeatedly.
    if (interaction.type === 3 && customId === "birthday:curseinput") {
      return showBirthdayCurseModal(env, interaction);
    }

    // Talent Show text submissions must open a modal as the initial response.
    if (interaction.type === 3 && customId === "talent:text") {
      return showBirthdayTalentModal(env, interaction);
    }
    if (interaction.type === 5 && customId === "talent:modal") {
      const performance = getModalTextInput(interaction, "performance");
      return birthdayTalentAddSubmission(env, interaction, performance, null);
    }

    if (interaction.type === 3 && customId === "truthpass:answer") {
      return showBirthdayTruthPassModal(env, interaction);
    }
    if (interaction.type === 5 && customId === "truthpass:modal") {
      const answer = getModalTextInput(interaction, "truth_answer");
      return birthdayTruthPassAnswer(env, interaction, answer);
    }

    // Sparkle Crime SOLO start: use a complete type-4 response as the
    // initial Discord response. This path intentionally does NOT use a
    // deferred "thinking" response. The case itself is generated immediately
    // from local data, while the player record is persisted in waitUntil().
    // This isolates SOLO from the deferred-response path that was leaving
    // Discord stuck on "MyTree is thinking...".
    if (isCrimeCommand) {
      const crimeSub = interaction.data?.options?.find(option => option.type === 1)?.name || "solo";
      if (crimeSub === "solo") {
        try {
          const user = getUserFromInteraction(interaction);
          if (!user) {
            return new Response(JSON.stringify({
              type: 4,
              data: { content: "❌ I couldn't determine your Discord account.", flags: 64 }
            }), { status: 200, headers: { "Content-Type": "application/json" } });
          }

          // Only this one KV read happens before Discord's initial response.
          // Everything else is local and/or background work.
          const player = await getPlayer(env, user.id);
          const punishment = activePunishment(player);
          if (["corner", "court_game", "court_shame_corner"].includes(punishment)) {
            return new Response(JSON.stringify({
              type: 4,
              data: { content: punishmentBlockedText(player, punishment), flags: 64 }
            }), { status: 200, headers: { "Content-Type": "application/json" } });
          }

          if (player.sparkleCrimeSolo?.status === "playing") {
            return new Response(JSON.stringify({
              type: 4,
              data: { content: "❌ You already have a detective case open. Finish it first.", flags: 64 }
            }), { status: 200, headers: { "Content-Type": "application/json" } });
          }

          updatePlayerIdentity(player, interaction);
          const game = crimeCreateCase(1);
          game.ownerId = user.id;
          game.mode = "solo";
          player.sparkleCrimeSolo = game;

          const responseData = {
            content: crimeCaseText(game, true),
            components: crimePrivateRows(game),
            flags: 64
          };

          // Persist after the complete response has already been sent to Discord.
          ctx.waitUntil((async () => {
            try {
              await savePlayer(env, player, user.id);
            } catch (error) {
              console.error("Sparkle Crime solo save failed:", error);
            }
          })());

          return new Response(JSON.stringify({ type: 4, data: responseData }), {
            status: 200,
            headers: { "Content-Type": "application/json" }
          });
        } catch (error) {
          console.error("Sparkle Crime solo fast-path error:", error);
          return new Response(JSON.stringify({
            type: 4,
            data: {
              content: `❌ **Couldn't open the detective case.**\n\n\`${error?.message || "Unknown error"}\``,
              flags: 64
            }
          }), { status: 200, headers: { "Content-Type": "application/json" } });
        }
      }
    }

    // =========================================================
    // BOMB FAST-PATH
    //
    // Bomb components can perform KV reads/writes. Do NOT use a type-6
    // component update here: Discord can reject that acknowledgement when
    // the Bomb message/component is not in the exact state Discord expects.
    // A normal public type-5 deferred response is much more reliable. It
    // creates a public @original immediately, and the Bomb handler edits
    // that response after the KV work finishes.
    // =========================================================
    if (isBombComponent) {
      const ack = await fetch(
        `https://discord.com/api/v10/interactions/${interaction.id}/${interaction.token}/callback`,
        {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ type: 5, data: { flags: 64 } })
        }
      );

      if (!ack.ok) {
        console.error("Bomb deferred response failed:", ack.status, await ack.text());
        return new Response("OK", { status: 200 });
      }

      interaction.__deferred = true;
      interaction.__deferredUpdate = false;
      interaction.__deferredEphemeral = false;

      ctx.waitUntil((async () => {
        try {
          const user = getUserFromInteraction(interaction);
          const blacklisted = user && user.id !== env.OWNER_ID
            ? await isUserBlacklisted(env, String(user.id))
            : false;

          if (blacklisted) {
            await sendBombPublicText(
              env,
              interaction,
              `🚫 **Access Restricted**\n\nYou currently cannot use the Werewives bot.`,
              []
            );
            return;
          }

          const bombRestriction = await checkBombRestriction(env, interaction);
          if (bombRestriction) {
            await sendBombPublicText(env, interaction, bombRestriction, []);
            return;
          }

          await handleBombComponent(env, interaction, ctx, url.origin);
        } catch (error) {
          console.error("Bomb interaction error:", error);
          try {
            const response = await editOriginalResponse(env, interaction, {
              content: `❌ **Bomb error:** ${error?.message || "Unknown error"}`,
              components: []
            });
            if (!response.ok) {
              console.error("Bomb error response edit failed:", response.status, await response.text());
            }
          } catch (editError) {
            console.error("Could not send Bomb error message:", editError);
          }
        }
      })());

      return new Response("OK", { status: 200 });
    }

    if (relevant) {
      let update = false;
      let ephemeral = false;

      if (isSparkleShopCommand) {
        ephemeral = true;
      } else if (isNewsCommand || isBlacklistCommand) {
        ephemeral = true;
      } else if (isBattleCommand) {
        ephemeral = interaction.data?.name === "battleshop" || interaction.data?.name === "battle-end";
      } else if (isSoloCommand) {
        const sub = interaction.data?.options?.find(option => option.type === 1)?.name || "start";
        ephemeral = ["status", "end", "leaderboard"].includes(sub);
      } else if (isCrimeCommand) {
        const sub = interaction.data?.options?.find(option => option.type === 1)?.name || "solo";
        ephemeral = ["solo", "status", "leaderboard", "end"].includes(sub);
      } else if (isColorCommand) {
        ephemeral = true;
      } else if (isExperimentCommand) {
        const sub = interaction.data?.options?.find(option => option.type === 1)?.name || "create";
        ephemeral = sub === "end";
      } else if (isPastelCommand) {
        // Color Chaos lobbies must be public so other players can actually see
        // and join them. Only the end-game command remains private.
        const sub = interaction.data?.options?.find(option => option.type === 1)?.name || "create";
        ephemeral = ["end", "leaderboard"].includes(sub);
      } else if (isCourtCommand) {
        // Raccoon Court is a public community feature.
        ephemeral = false;
      } else if (isFreeCommand || isTitlesCommand || isPunishmentCommand) {
        // FREE guesses and the Titles menu are private.
        ephemeral = true;
      } else if (isHeistCommand) {
        const sub = interaction.data?.options?.find(option => option.type === 1)?.name || "status";
        ephemeral = ["join", "leave", "start", "status", "end"].includes(sub);
      } else if (isIslandCommand) {
        const sub = interaction.data?.options?.find(option => option.type === 1)?.name || "status";
        ephemeral = ["rules", "status"].includes(sub);
      } else if (isCoupCommand) {
        const sub = interaction.data?.options?.find(option => option.type === 1)?.name || "status";
        ephemeral = ["join", "leave", "start", "status", "roles", "stats", "end"].includes(sub);
        if (sub === "create") ephemeral = false;
      } else if (isRumbleCommand) {
        const sub = interaction.data?.options?.find(option => option.type === 1)?.name || "status";
        ephemeral = ["join", "leave", "start", "status", "end"].includes(sub);
        if (sub === "create") ephemeral = false;
      } else if (isCrimeComponent) {
        const action=String(interaction.data.custom_id).split(":")[1];
        if(["join","leave","start","create","end"].includes(action)) update=true;
        else ephemeral=true;
      } else if (isCoupComponent) {
        const action = String(interaction.data.custom_id).split(":")[1];
        // Lobby controls update the public board. All in-game decisions,
        // target choices, challenges, blocks, and responses stay private.
        if (["join", "leave", "start"].includes(action)) update = true;
        else ephemeral = true;
      } else if (isRumbleComponent) {
        const action = String(interaction.data.custom_id).split(":")[1];
        // The initial Open My Actions button creates the one private menu.
        // Once that private menu exists, all of its buttons MUST use a type-6
        // update ACK so Discord edits that same ephemeral message instead of
        // creating a brand-new message on every click.
        // Lobby buttons still update the public lobby; status/end remain private.
        if (["join", "leave", "start"].includes(action)) {
          update = true;
        } else if (["choose", "target", "action"].includes(action)) {
          update = true;
        } else {
          ephemeral = true;
        }
      } else if (isExperimentComponent) {
        const action = String(interaction.data.custom_id).split(":")[1];
        if (action === "vote" || action === "clue" || action === "status") ephemeral = true;
        else update = true;
      } else if (isHeistComponent) {
        ephemeral = true;
      } else if (isIslandComponent) {
        const action = String(interaction.data.custom_id).split(":")[1];
        update = ["join", "leave", "rounds", "back", "start", "choice"].includes(action);
      } else if (isBattleComponent) {
        update = true;
      } else if (isPastelComponent) {
        update = true;
      } else if (isBirthdayComponent) {
        update = true;
      } else if (isHalloweenComponent && (customId === "collection:halloween:open" || customId.startsWith("collection:halloween:page:"))) {
        // The visual book is rendered with Puppeteer and can take longer than
        // Discord's component acknowledgement window. Defer privately first,
        // then sendHalloweenBook() edits the deferred @original with the image.
        update = false;
        ephemeral = true;
      } else if (isHalloweenComponent) {
        update = true;
      } else if (isPermanentGameComponent || isPermanentGameModal) {
        update = true;
      } else if (isTitlesComponent) {
        update = true;
      } else if (isSparkleShopComponent) {
        update = true;
        ephemeral = true;
      } else if (isNewsComponent) {
        update = true;
        ephemeral = true;
      } else if (isSurpriseAlertComponent) {
        // The alert is an ephemeral follow-up message. Updating the
        // component interaction edits that private alert in place.
        update = true;
        ephemeral = true;
      } else if (isTreeComponent) {
        // Tree actions should update the existing /tree message rather than
        // showing a long-running ephemeral "Bot is thinking..." state.
        update = true;
      } else if (isBadgeComponent) {
        // Badge management is PRIVATE. Use a deferred ephemeral response
        // instead of a type-6 update, which would edit the public /profile.
        // sendText() will then edit this private original response.
        ephemeral = true;
        update = false;
      } else if (isCustomizeComponent) {
        // Customize menus and equip actions can perform KV reads/writes.
        // Acknowledge immediately so Discord does not leave the button
        // spinning on "Bot is thinking..." while the menu is rebuilt.
        update = true;
            } else if (isRaccoonMartComponent) {
        // RaccoonMart handlers edit the private shop/menu after KV work.
        update = false;
        ephemeral = true;
      } else if (isShopComponent) {
        // Shop handlers edit the existing shop message after KV work.
        // A type-6 update ACK removes the Discord "Bot is thinking..."
        // state immediately and avoids leaving the button interaction
        // spinning while the shop is being rebuilt.
        update = true;
      }

      const responseType = update ? 6 : 5;
      const responseData = ephemeral && !update ? { flags: 64 } : {};

      // Mark the interaction as already acknowledged so the handlers edit
      // the deferred response instead of trying to acknowledge it a second time.
      interaction.__deferred = true;
      interaction.__deferredUpdate = update;
      interaction.__deferredEphemeral = ephemeral;

      ctx.waitUntil((async () => {
        try {
          const user = getUserFromInteraction(interaction);
          const isNewsAcknowledgement = isNewsComponent;
          const blacklisted = user && user.id !== env.OWNER_ID ? await isUserBlacklisted(env, String(user.id)) : false;
          if (blacklisted && !isNewsAcknowledgement) {
            if (interaction.type === 3) await sendEphemeralFollowup(env, interaction, "🚫 **Access Restricted**\n\nYou currently cannot use the Werewives bot. If you believe this was a mistake, contact the bot owner.");
            else await sendText(env, interaction, "🚫 **Access Restricted**\n\nYou currently cannot use the Werewives bot. If you believe this was a mistake, contact the bot owner.");
            return;
          }
          if (!isPunishmentCommand && !isNewsAcknowledgement) await maybeShowSurpriseAlert(env, interaction);
          await maybeCourtWatch(env, interaction);
          await maybePublicShame(env, interaction);
          await maybeSpoonInvestigation(env, interaction);
          if (interaction.type === 2 || interaction.type === 3) {
            const bombRestriction = await checkBombRestriction(env, interaction);
            if (bombRestriction) {
              await sendPublicText(env, interaction, bombRestriction, []);
              return;
            }
          }
          if (interaction.type === 2) {
            await handleCommand(env, interaction);
          } else {
            await handleComponent(env, interaction);
          }
          if (!isNewsAcknowledgement) await maybeShowNews(env, interaction);
        } catch (error) {
          console.error("Interaction error:", error);
          try {
            await editOriginalResponse(env, interaction, {
              content: `❌ Something went wrong: ${error?.message || "Unknown error"}`
            });
          } catch (editError) {
            console.error("Could not send interaction error message:", editError);
          }
        }
      })());

      return new Response(
        JSON.stringify({ type: responseType, data: responseData }),
        {
          status: 200,
          headers: { "Content-Type": "application/json" }
        }
      );
    }

    try {
      if (interaction.type === 2) {
        await handleCommand(env, interaction);
      } else if (interaction.type === 3) {
        await handleComponent(env, interaction);
      }
      return new Response("OK", { status: 200 });
    } catch (error) {
      console.error("Interaction error:", error);
      return new Response("OK", { status: 200 });
    }
  },


/* =======================================================
   SCHEDULED TASKS

   Cloudflare cron should be configured separately
   in Cloudflare Worker Settings → Triggers → Cron Triggers.

   Every scheduled pass checks:
   - Raccoon Heist timers
   - Chaos Island round timers

   Standalone hourly Chaos Events are disabled; Chaos Island is now
   the main home for chaos gameplay.
======================================================= */

  async scheduled(
    event,
    env,
    ctx
  ) {
    ctx.waitUntil(
      Promise.all([
        processHeistTimers(
          env
        ),
        processRumbleTimers(
          env
        ),
        processChaosIslandTimers(
          env
        ),
        processPastelTimers(
          env
        ),
        processCourtTrashRelease(env),
        processBirthdayEvent(env),
        expireBirthdayEventState(env),
        processRaccoonMegaphoneJobs(env),
        processRaccoonSuitPaydays(env),
        processRaccoonEmpireDividends(env)
        ,processBombTimers(env)
      ])
    );
  }
}
